/* المُلهم، بيانات برنامج «تعلّم» الثاني: التفكير بالنظرية أم التفكير بالنموذج؟ */
window.HH_LEARN=window.HH_LEARN||{};window.HH_LEARN.nmodel={"title":"التفكير بالنظرية أم التفكير بالنموذج؟","chapters":[{"k":"intro","t":"المقدمة","q":"ما المهام الأربع للباحث الاجتماعي؟ وأيها الأصعب؟","sections":[{"t":"مهام الباحث الاجتماعي الأربع","p":["يسعى الباحث الاجتماعي لصناعة معرفة نسقيّة في التعامل مع السلوك الإنساني تجاه ظاهرةٍ ما، وهو ما يعينه على الفهم أو التفسير أو التنبؤ أو التقييم، وهذا ما يميّز الباحث الاجتماعي عن سواه من عموم المتابعين للشأن العام. وصناعة هذه المعرفة النسقية تعني أن للباحث الاجتماعي أربع مهام أساسية:","فالمهمة الوصفية تبحث في سؤال \"ما الذي يجري؟\"، وما يتفرع عنه من أسئلة، مثل: أين ومتى وكيف يجري؟ أما المهمة التفسيرية فتبحث عن سؤال: \"لماذا يجري؟\"، والمهمة التنبؤية تبحث في سؤال: \"ما الذي سيجري؟\". أما المهمة المعيارية فهي متعلقة بسؤال: \"ما الذي ينبغي أن يجري؟\". ويتضح من ذلك أن المهمتين الوصفية والتفسيرية مهمتان بعديّتان؛ أي بعد وقوع الحدث، في حين المهمة الاستشرافية مهمة قبليّة، أما المعيارية فهي حاضرة من قبلُ ومن بعدُ."],"key":"المهمتين الوصفية والتفسيرية مهمتان بعديّتان؛ أي بعد وقوع الحدث، في حين المهمة الاستشرافية مهمة قبليّة، أما المعيارية فهي حاضرة من قبلُ ومن بعدُ.","items":[{"h":"المهمة الأولى: الوصف","x":"وذلك برصد السلوك الإنساني ومتعلقاته كما هي متحققة في الواقع، وغاية الوصف صناعة الفهم."},{"h":"المهمة الثانية: التفسير","x":"وهي تسبيب نظام العلاقات بين الظواهر ومدخلاتها ومخرجاتها، وغاية التفسير صناعة المعنى."},{"h":"المهمة الثالثة: التنبؤ","x":"وهو التعويل على قواعد معرفية موجِّهة لاستشراف السلوك الإنساني، وغاية التنبؤ صناعة التهيؤ."},{"h":"المهمة الرابعة: التقييم","x":"وهذه تعبر عن المعرفة المعيارية تجاه السلوك الإنساني، وغاية التقييم صناعة الموقف."}]},{"t":"لماذا التنبؤ هو الأصعب؟","p":["ومهمة التنبؤ هي الأصعب من بين المهام الأربع؛ لأن التنبؤ يتمرحل قبل الحدث كما ذكرنا، وهذا يقتضي أن الباحث أمام احتمالات متعددة لاتجاه السلوك الإنساني، في حين التفسير لا يبدأ إلا بعد أن يحسم الإنسان موقفه ويتخذ قراره، فالتفسير يكون في مواجهة خيار واحد، أما التنبؤ فهو أمام خيارات متعددة، وهو ما يجعله أكثر صعوبة وتعقيدًا. والذي تبتغيه هذه الورقة هو البحث في مهمّتي التفسير والتنبؤ في التحليل السياسي، متسائلةً عن جدوى التعويل على النظرية في الوصول إليهما.","ومن المهم التوضيح هنا أن هذه الدراسة تتعاطى مع حقل التحليل السياسي بوصفه الوظيفة المباشرة واللازمة لحقل العلاقات الدولية، فلا تؤمن هذه الدراسة بالحدود المصطنعة بين الحقلين كما هو سائد في الأدبيات الأكاديمية، وإنما ترى أن الترابط بينهما في حركة الواقع ترابطٌ عضوي لا ينفصل إلا على المستوى الذهني والتجريدي."],"key":"فالتفسير يكون في مواجهة خيار واحد، أما التنبؤ فهو أمام خيارات متعددة، وهو ما يجعله أكثر صعوبة وتعقيدًا."},{"t":"خطة الدراسة","p":["وقد جاءت هذه الدراسة وفقًا للمباحث الآتية:"],"items":[{"h":"المبحث الأول","x":"مركزية الفرد في التحليل السياسي."},{"h":"المبحث الثاني","x":"مفهوم النظرية ومعضلة التعميم."},{"h":"المبحث الثالث","x":"ما جدوى النظريات في التفسير والتنبؤ؟"},{"h":"المبحث الرابع","x":"النظريات إضافة مجانية أم إضافة مكلفة؟"},{"h":"المبحث الخامس","x":"من التفكير بالنظرية إلى التفكير بالنموذج."}]}],"examples":[],"quotes":[],"notes":["والاقتصار على التفسير والتنبؤ لأن بقية الوظائف لا تتطلب نظريات، فالوصف يتوقف على المعلومة، والتقييم يتوقف على المرجعية، أما التفسير والتنبؤ فالتعويل عادةً على النظريات، وإن كانت النظرية تُستثمر في التفسير أكثر منها في التنبؤ."],"quiz":[{"q":"ما غاية مهمة التفسير عند الباحث الاجتماعي كما يحددها المؤلف؟","o":["صناعة المعنى","صناعة الفهم","صناعة التهيؤ","صناعة الموقف"]},{"q":"أي المهام الأربع يصفها المؤلف بأنها الأصعب؟","o":["التنبؤ","الوصف","التفسير","التقييم"]},{"q":"لماذا كان التنبؤ أصعب من التفسير؟","o":["لأن التنبؤ أمام خيارات متعددة، والتفسير أمام خيار واحد","لأن التنبؤ لا يحتاج إلى معلومات","لأن التفسير يقع قبل الحدث","لأن التنبؤ مهمة معيارية"]},{"q":"أي سؤال تبحث فيه المهمة المعيارية؟","o":["ما الذي ينبغي أن يجري؟","ما الذي يجري؟","لماذا يجري؟","ما الذي سيجري؟"]}],"sort":{"t":"بعدية أم قبلية؟","s":"صنّف كل مهمة بحسب وقتها من الحدث، كما في المقدمة.","bins":["بعد وقوع الحدث","قبل وقوع الحدث","من قبل ومن بعد"],"items":[["الوصف",0],["التفسير",0],["التنبؤ",1],["التقييم",2]]}},{"k":"ch1","t":"المبحث الأول: مركزية الفرد في التحليل السياسي","q":"هل تتحرك الدول وحدها، أم يقف وراء كل تحول فرد بعينه؟","sections":[{"t":"الباحث السياسي يدرس الفاعل ليفهم التفاعلات","p":["تُصنَّف السياسة والاقتصاد وعلم الاجتماع والتربية ضمن ما يسمى العلوم الاجتماعية، وهذا التصنيف يؤدي إلى التعامل معها كأنها كتلة واحدة دون التدقيق في الفروقات المؤثرة بينها. والواقع أن دوائر التحليل السياسي تختلف عن دوائر التحليل الاجتماعي، ليس من حيث طبيعة الموضوع، فجميعها يدرس السلوك الإنساني، ولكن من حيث وحدة التفاعل. ذلك أن وحدة التحليل في سلوك الدولة ترتكز على الفرد نفسه كما تفترض هذه الورقة، في حين أن وحدة التحليل في الحقل الاجتماعي تتمحور حول التفاعلات باختلاف حقولها، فعلم الاجتماع مثلًا يرتكز على التفاعلات الاجتماعية بين الأفراد، ولا يدرس سلوك فرد بعينه، خلافًا لحقل السياسة الخارجية الذي يدرس صانع قرار معين ليفهم من خلاله طبيعة التفاعلات الدولية. فإذا كان الباحث الاجتماعي يدرس التفاعلات ليفهم الفاعل، فإن الباحث السياسي يدرس الفاعل ليفهم التفاعلات.","لقد ذكر فريد جرينشتاين (Fred I. Greenstein) أن الكثير من النشاط السياسي لا يمكن تفسيره إلا باستحضار شخصيات الفاعلين السياسيين. وهذا صحيح إن كان الحديث عن النشاط السياسي عمومًا، أما إن كان عن صناعة القرار تحديدًا فيمكن المجازفة بالقول إنه يصعب عدم استحضار شخصيّة فاعل بعينه عند تحليل السلوك السياسي، إذ المتأمل في لحظات التغير في سلوكيات الدول يجد وراءها فردًا بعينه؛ تختلف مساحة حركته باختلاف طبيعة تموضعه في النظام السياسي وارتباطاته الخارجية.","نعم قد تكون هناك تحولات وأحداث وجماعات تدفع باتجاه التغيير، لكن في نهاية المطاف ثمة فرد (صانع قرار) اقتنع بالتغيير فحصل، ولو أراد هذا الفرد مقاومة التحولات أو ضغوطات البنى بمختلف أنماطها لاستطاع ذلك. ولا فرق في ذلك بين النظام الديمقراطي وغيره إلا في درجة التأثير لا في أصل الوجود."],"key":"فإذا كان الباحث الاجتماعي يدرس التفاعلات ليفهم الفاعل، فإن الباحث السياسي يدرس الفاعل ليفهم التفاعلات."},{"t":"شواهد من تحولات الدول","p":["إذ يصعب مثلًا إنكار أن السياسة الأمريكية قد تغيرت تغيرًا كبيرًا مع مجيء الرئيس دونالد ترامب، ويصعب كذلك إنكار أن نظامًا مليئًا بالمؤسسات البيروقراطية كالاتحاد السوفيتي قد تغير سريعًا مع ميخائيل غورباتشوف، كما ويصعب نفي أنّ دولة مثل السعودية استمرت على سياستها لأكثر من سبعين عامًا، تغيرت بشكل جذري بعد مجيء فرد واحد، وهو الأمير محمد بن سلمان. ومثل ذلك في بريطانيا، أقدم ديمقراطية في العالم، التي كانت مندفعة جدًا مع الولايات المتحدة الأمريكية في مطلع الألفية بسبب العلاقات الشخصية بين توني بلير (Tony Blair) وجورج بوش (George W. Bush)، إلى مستوى أن بلير خالف أغلبية حزبه وشعبه وذهب للحرب معه، وهو ما تغير بعد مجيء جوردون براون (Gordon Brown) الذي لم يكن يميل إلى الولايات المتحدة فشاب العلاقة بين البلدين حينها شيء من البرود.","وفي عهد جون غورتون (John Gorton) كانت أستراليا منهمكة في تطوير سلاح نووي، لكن حين تولّى السلطة غوف وايتلام (Gough Whitlam)، الذي كان يميل إلى المسالمة والتبعية، قرر ترك الاستراتيجية النووية التي تبنتها أستراليا في عهد غورتون! والفارق بين الموقفين يعود لاختلاف طبيعة الشخصين أكثر منه اختلاف في طبيعة البنى.","وفي عهد الرئيس الأمريكيّ ريتشارد نيكسون (Richard Nixon) كان الموقف الأمريكي تجاه النزاع الباكستاني الهندي مائلًا لصالح باكستان، ولم يكن ذلك بسبب الدوائر المؤسسية بقدر ما كان موقفًا ناشئًا عن دوافع شخصية؛ فقد كان بين الرئيس نيكسون وبين أنديرا غاندي عداء شخصي، في الوقت الذي كانت علاقته وثيقة بالرئيس الباكستاني يحيى خان! والأمر نفسه مع جون كينيدي (John Kennedy) حين توترت علاقة أمريكا بكندا في فترته، ولكن سرعان ما تلاشى هذا التوتر حين رحل جون ديفينبيكر (John Diefenbaker) وحل محله ليستر بيرسون (Lester B. Pearson)، والعلاقات الأمريكية الألمانية تدهورت في مطلع الثمانينات بسبب العلاقة السيئة بين الرئيس الأمريكي جيمي كارتر (Jimmy Carter) والمستشار الألماني هيلموت شميث (Helmut Schmidt)، وقد كانت مزدهرة قبل ذلك بسبب العلاقة الودية بين وزير الخارجية الأمريكي آنذاك فوستر دالاس (John Foster Dulles) والمستشار الألماني كونراد أديناور (Konrad Adenauer).","هذه كلها نماذج على دول تتمتع بقيود مؤسسية معروفة وراسخة، ومع ذلك تشكّلت علاقاتها الدولية في مرحلةٍ ما بسبب شخصيات صناع القرار فيها، وهذا كله يثبت صعوبة تنحية الفرد من مركزية صنع القرار مهما اختلفت طبائع الأنظمة السياسية، وأن الفرد هو وحدة التحليل المركزية حتى في ظل تضخم البنى السياسية وتعقّدها."],"key":"الفرد هو وحدة التحليل المركزية حتى في ظل تضخم البنى السياسية وتعقّدها."},{"t":"أين يقف الفرد في نظريات العلاقات الدولية؟","p":["وحديثنا عن مركزية الفرد في التحليل ينسجم أكثر مع نظريات الفاعلية (agency theories) التي تعوّل على دور الفاعل في صناعة السياسة الخارجية أكثر من تعويلها على دور البنية. وفيها نجد نظرياتٍ من قبيل نظريات تحليل السياسة الخارجية التي تنظر في دور صانع القرار في صناعة السياسة الخارجية. وكذلك الواقعية الكلاسيكية المتجلية في أعمال المنظّر الواقعي هانز مورغنثاو (Hans Morgenthau)، والتي تستوعب أثر الطبيعة البشرية ومكنوناتها في تفسير سلوكات الدول على الساحة الدولية. وهذا الاتجاه يخالف اتجاهات أخرى تعطي أولوية للبنية على الفاعل، مثل نظريات التيار السائد الليبرالية الجديدة والواقعية الجديدة، وكذلك المقاربة البنائية لألكسندر ونت. والنظريات الدولية عمومًا تقترب وتبتعد من الفرد، لكنها لا تنطلق من كونه مركزًا، فالماركسية مثلًا تعوّل على القوى المادية في تسبيب الظواهر، وهكذا هو شأن نظرية التبعية (Dependency theory). في حين نجد الليبرالية الجديدة ترتكز على دور البنى والمؤسسات في التوصل للتعاون الدولي، بخلاف الواقعية الجديدة التي يغلب عليها التشاؤم حيال إمكانية التعاون وتنظر في طبيعة تموضع الدولة إقليميًا ودوليًا كمحدد مفسر لطبيعة سلوكها. وهكذا نجد الفرد غائبًا إلا كمستوى عابر من مستويات التحليل دون أن يكون له التمركز الملائم لطبيعته الواقعية.","وقد تبدو نظرية الدور (Role Theory) استثناءً في تمركزها حول الفرد، لكن ذلك لا يبدو دقيقًا؛ لأن نظرية الدور وإن كانت تسعى لفهم صناعة القرار من خلال صانع القرار نفسه، إلا أنها لا تسعى لذلك من خلال دراسة إرادته وقدرته وطريقته، بل من خلال زاوية واحدة، وهي تصور صانع القرار لطبيعة الدور الملائم لدولته إقليميًا ودوليًا.","ونشير إلى أن الحديث عن الفرد هنا لا علاقة له بالمعركة القائمة في علم النفس السياسي بين تيّاري الموقفية (Situationism) والنزوعية (Dispositionism)، لأن هذا الجدل يتمحور حول مصادر وعي صانع القرار التي تشكّل سلوكه السياسي، أهي ذاتية المنشأ كما تفترض النزوعية؟ أم أنها نتاج البيئة المحيطة بالفرد كما ترى الموقفية؟ هذا النقاش ليس مهمًا هنا؛ لأن هذه الدراسة لا تناقش \"مصادر\" صانع القرار، بل \"دور\" صانع القرار ومستوى تأثيره في ظل القيود البنيوية والمؤسسية، بصرف النظر عن منشئها النفسي أو البيئي."],"key":"وهكذا نجد الفرد غائبًا إلا كمستوى عابر من مستويات التحليل دون أن يكون له التمركز الملائم لطبيعته الواقعية."},{"t":"فرضية الدراسة: الفرد لا الصندوق الأسود","p":["الشاهد أن الفرضية التي تتبناها هذه الدراسة هي أن الفرد هو الوحدة المركزية في تحليل السلوك الدولي، بعيدًا عن الاتجاه الشائع في أدبيات الحقل القائمة على افتراض \"عقلانية الدولة\"، وأن الدولة عبارة عن صندوق أسود Black Box لا يصدر عنه سوى الاختيارات العقلانية. هذا الاتجاه في الحقيقة اقتضته نزعة التماهي مع العلوم الطبيعية السائدة في العلوم الاجتماعية، والتي تبتغي اصطناع حالة من الحتمية في التنبؤات السياسية بما يقرّبها من نموذج التنبؤ في الطبيعيات.","وافتراض عقلانية الدولة ربما يسهم في \"تيسير\" التحليل، لكنه لا يسهم في \"دقة\" التحليل، ولذلك تجد الباحثين لا يعوّلون على هذا الافتراض المتخيّل إلا في أبحاثهم الأكاديمية، أما عمليًا في الحوارات المباشرة، لا سيما في دوائر صناعة القرار، تجدهم يتمركزون حول شخصيات صناع القرار في تفسير واستشراف سلوكيات الدول.","ولا يعني ما سبق الوقوع في فخ الاختزالية (Reductionism)؛ لأننا نقول إن صناعة القرار في السياسة تتمركز حول الفرد، والتمركز لا ينفي ما سواه بقدر ما يثبت أولويته، فلا شك أن هناك بنى مؤسسية ودوائر معنية بصناعة القرار، لكن هذا لا ينفي وجود مرتكز لهذه العملية تستند إليه، وهو فردٌ بعينه. فالذي نفترضه أن البُنى مهما اختلفت أو تضخمت أو تعقّدت فإن تحليل صناعة القرار يبقى متمحورًا حول الفرد، وإن لم يقف عند حدوده بطبيعة الحال. فعلى سبيل المثال، حين ندرس سلوك الدولة الإسرائيلية؛ من الطبيعي الانطلاق من شخصية بنيامين نتنياهو (Benjamin Netanyahu) نفسه، فلو كان هناك شخص آخر غير نتنياهو في السلطة لكان سلوك إسرائيل مختلفًا في تدبير حرب السابع من أكتوبر، ولا ينفي ذلك دور المؤسسات الإسرائيلية التشريعية والأمنية، لكنه يؤكد على أن لنتنياهو اليد العليا في تحديد السياسة الإسرائيلية."],"key":"والتمركز لا ينفي ما سواه بقدر ما يثبت أولويته"}],"examples":[{"who":"دونالد ترامب والولايات المتحدة","x":"يصعب مثلًا إنكار أن السياسة الأمريكية قد تغيرت تغيرًا كبيرًا مع مجيء الرئيس دونالد ترامب","pg":10},{"who":"ميخائيل غورباتشوف والاتحاد السوفيتي","x":"ويصعب كذلك إنكار أن نظامًا مليئًا بالمؤسسات البيروقراطية كالاتحاد السوفيتي قد تغير سريعًا مع ميخائيل غورباتشوف","pg":11},{"who":"الأمير محمد بن سلمان والسعودية","x":"كما ويصعب نفي أنّ دولة مثل السعودية استمرت على سياستها لأكثر من سبعين عامًا، تغيرت بشكل جذري بعد مجيء فرد واحد، وهو الأمير محمد بن سلمان.","pg":11},{"who":"توني بلير وجورج بوش وجوردون براون (بريطانيا والولايات المتحدة)","x":"ومثل ذلك في بريطانيا، أقدم ديمقراطية في العالم، التي كانت مندفعة جدًا مع الولايات المتحدة الأمريكية في مطلع الألفية بسبب العلاقات الشخصية بين توني بلير وجورج بوش، إلى مستوى أن بلير خالف أغلبية حزبه وشعبه وذهب للحرب معه، وهو ما تغير بعد مجيء جوردون براون الذي لم يكن يميل إلى الولايات المتحدة فشاب العلاقة بين البلدين حينها شيء من البرود.","pg":11},{"who":"جون غورتون وغوف وايتلام (أستراليا)","x":"وفي عهد جون غورتون كانت أستراليا منهمكة في تطوير سلاح نووي، لكن حين تولّى السلطة غوف وايتلام، الذي كان يميل إلى المسالمة والتبعية، قرر ترك الاستراتيجية النووية التي تبنتها أستراليا في عهد غورتون! والفارق بين الموقفين يعود لاختلاف طبيعة الشخصين أكثر منه اختلاف في طبيعة البنى.","pg":11},{"who":"ريتشارد نيكسون وأنديرا غاندي ويحيى خان (أمريكا وباكستان والهند)","x":"وفي عهد الرئيس الأمريكيّ ريتشارد نيكسون كان الموقف الأمريكي تجاه النزاع الباكستاني الهندي مائلًا لصالح باكستان، ولم يكن ذلك بسبب الدوائر المؤسسية بقدر ما كان موقفًا ناشئًا عن دوافع شخصية؛ فقد كان بين الرئيس نيكسون وبين أنديرا غاندي عداء شخصي، في الوقت الذي كانت علاقته وثيقة بالرئيس الباكستاني يحيى خان!","pg":11},{"who":"جون كينيدي وجون ديفينبيكر وليستر بيرسون (أمريكا وكندا)","x":"والأمر نفسه مع جون كينيدي حين توترت علاقة أمريكا بكندا في فترته، ولكن سرعان ما تلاشى هذا التوتر حين رحل جون ديفينبيكر وحل محله ليستر بيرسون","pg":12},{"who":"جيمي كارتر وهيلموت شميث (أمريكا وألمانيا)","x":"والعلاقات الأمريكية الألمانية تدهورت في مطلع الثمانينات بسبب العلاقة السيئة بين الرئيس الأمريكي جيمي كارتر والمستشار الألماني هيلموت شميث","pg":12},{"who":"فوستر دالاس وكونراد أديناور (أمريكا وألمانيا)","x":"وقد كانت مزدهرة قبل ذلك بسبب العلاقة الودية بين وزير الخارجية الأمريكي آنذاك فوستر دالاس والمستشار الألماني كونراد أديناور.","pg":12},{"who":"بنيامين نتنياهو وإسرائيل (حرب السابع من أكتوبر)","x":"حين ندرس سلوك الدولة الإسرائيلية؛ من الطبيعي الانطلاق من شخصية بنيامين نتنياهو نفسه، فلو كان هناك شخص آخر غير نتنياهو في السلطة لكان سلوك إسرائيل مختلفًا في تدبير حرب السابع من أكتوبر، ولا ينفي ذلك دور المؤسسات الإسرائيلية التشريعية والأمنية، لكنه يؤكد على أن لنتنياهو اليد العليا في تحديد السياسة الإسرائيلية.","pg":16}],"quotes":[{"x":"الكثير من النشاط السياسي لا يمكن تفسيره إلا باستحضار شخصيات الفاعلين السياسيين","by":"فريد جرينشتاين (Fred I. Greenstein)، بنقل المؤلف","pg":9},{"x":"حتى في النظم الديمقراطية فإن عملية صنع القرار السياسي تتم من خلال عدد محدود من الأفراد يعملون في إطار من السرية التي تفرضها اعتبارات الأمن","by":"لويد جونسون (جنسن)، تفسير السياسة الخارجية","pg":10}],"notes":["تخالف حجتنا هذه أدبيات التيار السائد المتعلقة بالتغيير في النظام الدولي. فعلى سبيل المثال، يجادل روبرت جيلبين (Robert Gilpin) في كتابه (الحرب والتغيير في السياسة الدولية) بأنّ طبيعة النظام الدولي لم تتغير منذ آلاف السنين، وحتى التغييرات السياسية الكبرى تكون نتاج التقاء مجموعات فريدة وغير متوقعة من التطورات، وعادةً ما تنبع من فاعلين يفضلون الانفصال عن نظام توزيع السلطة القائم؛ لرغبتهم في الاستفادة من المنافع الناجمة عن تغيير هذا النظام. مع ذلك، تبقى الدولة وليس صانع القرار الوحدة الأساسية المحركة للتغيير في إسهامه.","ولا شك أن ذلك يقربنا من تبني موقف المنهجية الفردية Methodological individualism التي ترى أن كل موقف مركب يعود في الحقيقة إلى أفراد بعينهم تشكّل مواقفهم وميولهم الإطار الذي ينتمون إليه، وهو ما يقتضي التعويل على البعد النفسي في التفسير Psychologism."],"quiz":[{"q":"ما الفرق الذي يقرره المؤلف بين الباحث الاجتماعي والباحث السياسي؟","o":["الاجتماعي يدرس التفاعلات ليفهم الفاعل، والسياسي يدرس الفاعل ليفهم التفاعلات","كلاهما يدرس التفاعلات فقط","السياسي يدرس المجتمع، والاجتماعي يدرس الدولة","لا فرق بينهما في وحدة التحليل"]},{"q":"ما وحدة التحليل المركزية في سلوك الدولة كما تفترض الدراسة؟","o":["الفرد صانع القرار","المجتمع","النظام الدولي","المؤسسات البيروقراطية وحدها"]},{"q":"ماذا يقول المؤلف عن افتراض «عقلانية الدولة»؟","o":["قد يسهم في تيسير التحليل، لكنه لا يسهم في دقته","هو الافتراض الأدق في التحليل","يناسب صناع القرار في حواراتهم المباشرة","يلغي دور المؤسسات تماماً"]},{"q":"هل تعني مركزية الفرد إنكار دور المؤسسات؟","o":["لا، التمركز لا ينفي ما سواه بقدر ما يثبت أولويته","نعم، المؤسسات لا دور لها","نعم في النظم الديمقراطية فقط","لا، لأن المؤسسات هي المركز"]}],"match":{"t":"من غيّر سياسة دولته؟","s":"صل كل شاهد بما ذكره المؤلف عنه.","l":"الشاهد","r":"ما حدث","pairs":[["غوف وايتلام في أستراليا","ترك الاستراتيجية النووية التي تبنتها أستراليا في عهد غورتون"],["ميخائيل غورباتشوف","تغيّر الاتحاد السوفيتي سريعاً رغم كثرة مؤسساته البيروقراطية"],["توني بلير","خالف أغلبية حزبه وشعبه وذهب للحرب مع بوش"],["ريتشارد نيكسون","مال إلى باكستان بسبب عداء شخصي مع أنديرا غاندي"]]}},{"k":"ch2","t":"المبحث الثاني: مفهوم النظرية ومعضلة التعميم","q":"ما النظرية؟ ولماذا تفقد صفتها حين تغادر سياق نشأتها؟","sections":[{"t":"غموض مفهوم النظرية","p":["من المفارقات العجيبة في عالم الأفكار أن أكثر المفاهيم تكرارًا على ألسنتنا هي أكثرها غموضًا، كالحرية والحق والدين والثقافة والهوية والأخلاق وغيرها. ومصطلح \"النظرية\" مثال جيد على هذه المفارقة، فهي تبدو واضحة وبدهية بما يجعل تعريفها ترفًا، لكن الواقع أنها غامضة كما يظهر ذلك من استعمالاتها المختلفة. فهي تُطلق تارةً على المعرفة التفسيرية النسبية كالنظرية الانقسامية ونظرية التعلق، وتارة أخرى تُطلق على المعرفة الموجهة غير النسبية كنظرية التمثلات الاجتماعية ونظرية العلاج الانفعالي، كما وتأتي النظرية للتعبير عن المعرفة الوصفية غير التفسيرية كنظرية الأنوميا، وقد تعبّر أيضًا عن المعرفة المعيارية غير التفسيرية كنظرية الحرب العادلة والنظرية العسكرية Military theory.","هذه الاستعمالات المتنوعة أربكت مفهوم النظرية، وربما كثرة هذه الاستعمالات تعود إلى بريق ولمعان مصطلح النظرية نفسه، وقد ذكر جورج هومانز أنه \"لا يُستخدم لفظ ذو رنين في أحايين كثيرة كلفظ النظرية في العلوم الاجتماعية\".","ولمّا كانت النظرية هي محل البحث الأساس في هذه الدراسة، كان لا بد من توضيح المقصود بها حتى يستقيم الحكم عليها. وبناءً عليه، تقترح هذه الدراسة تعريف النظرية بأنها المعرفة التفسيرية المتحققة في سياقٍ ما."],"key":"تقترح هذه الدراسة تعريف النظرية بأنها المعرفة التفسيرية المتحققة في سياقٍ ما."},{"t":"عناصر النظرية الثلاثة","p":["يحدد هذا التعريف ثلاثة عناصر للنظرية:"],"key":"لأن التنبؤ لازمٌ للتفسير","items":[{"h":"العنصر الأول: المعرفة التفسيرية","x":"فالمعرفة الوصفية الإخبارية لا تعد نظرية، فمثلًا مصطلح الأنوميا الدوركايمي لا يعد نظرية؛ لأنه يصف المجتمع في حالة سيولة المعايير بما يجعل قدرته ضئيلة على التوجيه الأخلاقي لأفراده، لكنه لا يفسّر تلك الحالة. كما أن خاصية التفسير في النظرية تسمح بتمييزها عن الملاحظة، إذ الملاحظة إخبار لا تفسير، فهي تخبر عن حالة تم رصدها وملاحظتها، كقولنا: \"ازداد الطلاق في المجتمعات الخليجية\"، هذه ملاحظة وليست نظرية. وربما يلحظ القارئ عدم تضمن تعريف النظرية لعنصر التنبؤ، والواقع أنه لا حاجة لذلك؛ لأن التنبؤ لازمٌ للتفسير، فالتفسير هو تعليل ارتباط السبب بالمسبب، وبالتالي إذا وجد السبب سنتنبأ بوجود المسبب. والفارق بينهما يتمثل في التوقيت لا أكثر، فالتفسير مهمة بعديّة، إذ لا يمكن أن تفسّر الظاهرة أو القرار إلا بعد حدوثهما، والتنبؤ مهمة قبليّة، فلا تنبؤ بعد الوقوع."},{"h":"العنصر الثاني: التحقق","x":"وهذه الخاصية تهدف لتمييز النظرية عن الفرضية؛ لأن الفرضية معرفة تفسيرية كذلك، لكن ما يميزها عن النظرية أنها معرفة غير متحققة. فالفرضية هي النظرية قبل ثبوتها، والنظرية هي الفرضية بعد ثبوتها، ذلك أن الفرضية في الأصل تفسير مؤقت للظاهرة يضعه الباحث إلى أن يتأكد من ثبوته، فإن تأكد كانت نظرية وإلا فهي فرضية خاطئة، ولذلك العنصر الفارق بين النظرية والفرضية هو عنصر الاختبار."},{"h":"العنصر الثالث: معرفة سياقية","x":"وهذا يهدف لتمييز النظرية عن القانون الاجتماعي؛ لأن القانون الاجتماعي معرفة بدهية عابرة للسياقات، كقول الناس: \"كل ممنوع مرغوب\"، وقولهم: \"الصاحب ساحب\"، هذه معرفة تفسيرية تفسّر طوارئ السلوك الإنساني في حالة معينة، ولكنها قانون وليست نظرية؛ لأن النظرية ناتجة عن تأمل لظاهرة معينة في سياق محدد، ثم قد تتوافر معطيات هذا السياق في مكان آخر فيصح استثمار النظرية، وإلا فلا يصح، أما القانون الاجتماعي فهو غالبًا مطرد لا يخضع للنسبية الثقافية."}],"table":{"head":["الفارق","النظرية","القانون","الملاحظة"],"rows":[["النطاق","سياقي","مطرد","كلاهما"],["الطبيعة","تأملية","فطرية","كلاهما"],["الوظيفة","التفسير","التفسير","الوصف"]]}},{"t":"النظرية ومعضلة التعميم","p":["تكمن قيمة النظرية في قدرتها على التعميم، ولذلك يتسابق الباحثون على توظيفها في مختلف السياقات إيمانًا بعمومها، أما إذا فقدت النظرية هذه الميزة فستعود مجرد فرضية لا أكثر. وقد ذكرنا توًّا أن النظرية تكون فرضية حين تخرج من سياقها، وهذا يعني أن النظرية منتج قابل للتعميم، لكنه ليس عامًا بالضرورة.","ولتوضيح هذه الفكرة نقول إن كل نظرية اجتماعية لها مجالان:","تكون النظرية نظرية في مجال النشأة وحده، أما حين تنتقل إلى مجال الاستثمار فهي ليست سوى فرضية جيدة، نقول \"فرضية\" لفقدها عنصر الاختبار السياقي، ونقول \"جيدة\" لامتلاكها تاريخًا مساندًا ومؤيدًا، ويختلف مستوى جودة النظرية باختلاف مستوى ثبوتها واطرادها في السياقات المختلفة. ويأتي السؤال هنا: لماذا تتحول النظرية إلى فرضية حين تخرج من سياق نشأتها؟ بمعنى آخر: ما الذي يحول دون تعميم النظرية وتعديتها للسياقات الأخرى؟ يمكن رد ذلك إلى ثلاثة أسباب:"],"key":"وهذا يعني أن النظرية منتج قابل للتعميم، لكنه ليس عامًا بالضرورة.","items":[{"h":"مجال النشأة","x":"وهو السياق الذي اختُبرت فيه فرضية النظرية وثبت تحققها."},{"h":"مجال الاستثمار","x":"وهو السياق الذي يُراد توظيف النظرية فيه."}]},{"t":"السبب الأول: حرية الفاعل","p":["يختلف الفاعل الاجتماعي عن الفاعل الطبيعي في قضية جوهرية، وهي حرية الإرادة، فالفاعل الاجتماعي يتمتع بإرادة حرة، خلافًا للفاعل الطبيعي الذي يسير بنوعٍ من الحتمية، وهذه الإرادة الحرة هي أساس الفارق بين العلوم الاجتماعية والعلوم الطبيعية.","هل الطفل الذي ينشأ في بيئة أسرية واجتماعية سيكون مجرمًا في المستقبل؟ ربما يكون كذلك، لكن ربما يفاجئنا ويكون عالـمًا صالحًا. والمرء الذي يتعرض لظلم وضغوط اجتماعية كبيرة لا ندري إن كان سيكون هشًا فيستسلم وينتحر؟ أو يكون صلبًا فيقاوم وينتصر؟ وحاكم الدولة الكبيرة الفقيرة حين يكتشف ثروات هائلة في دولة صغيرة تجاوره يمكن أن نقول سيغزوها، أو ينافسها، أو حتى نقول أنّه لن يبالي بها، هكذا هو الإنسان لا نستطيع أن نجزم بخياراته.","أما الفاعل الطبيعي فلا يمتلك ترف الخيارات؛ لأنه لا يمتلك إرادة حرة، فشجرة الموز تنبت بطريقة محددة، وشجرة البرتقال تنبت بطريقة أخرى، وشجرة البطيخ بطريقة ثالثة، كل طريقة لها خطوات محددة، متى ما اختلّت الخطوات لم تنبت الشجرة، ومتى اكتملت تلك الخطوات لا يبقى للشجرة خيار في ألا تنبت وتنمو. لكن الإنسان ليس كالشجرة، ينمو بشروط ويتوقف بشروط، وإنما هو حر، قد يفاجئك بأنه وصل بلا شروطك التي وضعتها، وقد يفاجئك بأنه توقف مع وجود الشروط، فالإنسان لا ينتج سلوكه بناءً على قوانين حتمية (Deterministic)، وإنما على تفضيلات نفسية وثقافية مرنة.","هذه الحرية التي يتمتع بها الإنسان هي العائق الأساس الذي يقف في وجه طموح النظرية الاجتماعية لتعميم مضمونها، فالنظرية حين تبتغي التعميم فهي تفترض أن السلوك الإنساني سيطّرد بعد أن اختبرته في سياقٍ محدد، لكن الإنسان بإرادته الحرة وتفضيلاته اللانهائية، لا يمكن ضمان أن تطّرد النظرية معه.","وقد حاول الباحثون في العلوم الاجتماعية أن يعالجوا معضلة حرية الفاعل من خلال محاصرته في غايته ووسيلته، وذلك بافتراضهم أن الفاعل الاجتماعي يتحرك لتحقيق غاية واحدة، وهي \"المصلحة\"، ويتوسّل إليها بوسيلة واحدة، وهي \"العقلانية\". هكذا تبدو معضلة الحرية قد حُلّت، فالناس يتبعون مصالحهم، وهم يتبعونها بالطريقة العقلانية، وإذا كان الإنسان عادةً يبتغي مصلحته (الغاية) بالطريقة العقلانية (الوسيلة)، فإذن يمكن التنبؤ بخياره المستقبلي تجاه أي ظاهرة من خلال الجمع بين الغاية والوسيلة.","لكن هذا المخرج غيرُ مخرجٍ؛ لأن حرية الفاعل لا تزال تمارس دور العصا في عجلة النظرية؛ فليس صحيحًا أن الإنسان لا يتحرك إلا لأجل مصلحة، فربما يتحرك لدوافع نفسية لا نهائية، أو لتحقيق \"فعل مجاني\" على حد تعبير بيير بورديو (Pierre Bourdieu). كما أنه لو تحرك لأجل مصلحته فهذا لا يحسم الأمر؛ لأنه ليس بالضرورة أن يسعى لها بطريقة عقلانية لأي سبب من الأسباب، لا سيما أن \"أهواء البشر هي عمومًا أقوى من عقولهم\" على حد تعبير توماس هوبز (Thomas Hobbes)، وأن \"العقل ليس له سلطة إلا عند فئة قليلة من المثقفين، أما عموم الناس فتحكمها الأهواء\" على حد تعبير جون ستيورات ميل (John Stuart Mill).","فمثلًا قد نستمر في تحليل أسباب غزو الاتحاد السوفيتي لأفغانستان مستلهمين كل المعطيات الدولية والسياسية والأمنية والاقتصادية، ثم نكتشف أن الأمر لا علاقة له بكل تلك المسوغات العقلية، وإنما هي ردة فعل نفسية ناتجة عن حالة الإحباط النفسي التي مر بها رئيس الاتحاد السوفيتي ليونيد بريجينيف (Leonid Brezhnev) نتيجة رفض مجلس الشيوخ الأمريكي التصديق على معاهدة الحد من الأسلحة الاستراتيجية بين البلدين. هكذا نجد أن حرية الفاعل لا تزال تصر على عرقلة مشروع التعميم.","ثم إننا حتى لو سلّمنا بأن الإنسان لا يتحرك إلا لأجل مصلحته، ولا يسعى إليها إلا بسبل عقلانية، وتجاوزنا كل الجدل حول حرية الفاعل، فإن تعميم النظرية لا يزال عسيرًا للسببين الآتيين."],"key":"هذه الحرية التي يتمتع بها الإنسان هي العائق الأساس الذي يقف في وجه طموح النظرية الاجتماعية لتعميم مضمونها"},{"t":"السبب الثاني: نسبيّة الدافع","p":["لو افترضنا أن الإنسان ليس له دافع سوى سعيه لتحقيق مصلحته، فإن هذا لا يحل المعضلة؛ لأنَّ المصلحة مفهوم نسبي لا يمكن تعميمه، فهو يختلف من فاعل لآخر بحسب تصوراته الثقافية وميوله النفسية. فمن الناس من يفسّر المصلحة تفسيرًا اقتصاديًا صرفًا، ومنهم من يفسّرها تفسيرًا دينيًا، ومنهم من يفسّرها تفسيرًا ثقافيًا، ومنهم من يفسرها تفسيرًا اجتماعيًا (كالمكانة)، ومنهم من يفسّرها تفسيرًا مركبًا من عدة عوامل، هذا علاوةً على أن أوزان المصالح نفسها تتفاوت من سياق لآخر بما يعقّد حساباتها.","والعقلانية كالمصلحة، فلو سلّمنا أن كل فاعل يتوسّل بالعقلانية لتحقيق مصالحه، وأن الباحث يستطيع الاكتفاء بما يسميه أوغست كونت (Auguste Comte) \"التوقع العقلاني\"؛ فإن المعضلة تبقى في أنه لا يوجد مفهوم كوني للعقلانية، فما تراه عقلانيًا قد أراه طيشًا وتهورًا، وكل إنسان يرى نفسه عقلانيًا، ولذلك يقول أبو حامد الغزالي، رحمه الله: \"فما من أحد إلا وهو راض عن الله سبحانه في كمال عقله، وأشدهم حماقة وأضعفهم عقلًا هو أفرحهم بكمال عقله\". ويذكر رينيه ديكارت (René Descartes) أنَّ \"العقل أعدل الأشياء توزعًا بين الناس؛ لأن كل فرد يعتقد أنه قد أوتي منه الكفاية\".","إذن يمكن القول إنّه من الخطأ تعميم مفهومَي المصلحة والعقلانية، وإذا نفينا التعميم فقد سلبنا النظرية وقودها الذي تسير به، إذ ما قيمة النظرية لولا قدرتها على التعميم؟ لولا العموم لما كانت أكثر من فرضية."],"key":"لأنَّ المصلحة مفهوم نسبي لا يمكن تعميمه، فهو يختلف من فاعل لآخر بحسب تصوراته الثقافية وميوله النفسية."},{"t":"السبب الثالث: أداة التعدية","p":["حين تثبت فرضية في سياق ما وتتحول إلى نظرية، فإنَّ استثمارها يتحقق من خلال تعديتها إلى سياقات أخرى؛ أي الانتقال من مجال النشأة إلى مجال الاستثمار. وهذه التعدية تحصل في الحقيقة نتيجة أداة القياس، فهي التي تعطي النظرية مشروعية التعدية، وقد ذكر ديفيد باتريك (David P. Houghton) أن \"العلاقات الدولية مملوءة باستخدام القياس التاريخي\". ومن قبله بألف عام يقول ابن الأثير، رحمه الله: \"ما يحصل للإنسان من التجارب والمعرفة بالحوادث وما تصير إليه عواقبها، فإنه لا يحدث أمر إلا قد تقدم هو أو نظيره فيزداد بذلك عقلًا\".","لكن لكون القياس ناشئًا عن حالة جزئية واحدة، فإن الباحثين لا يكتفون به عادةً، وإنما يضطرون لمراكمة الأقيسة حتى يحكموا على الظاهرة، وتراكم الأقيسة هو ما يسمى بـ \"الاستقراء\". فإذا كان القياس هو الحكم على حالة مجهولة بناء على حالة معلومة، فإن الاستقراء هو الحكم على حالة مجهولة بناء على \"حالات\" معلومة، أو على حد تعبير روبير بلانشي (Robert Blanché) \"انطلاق من الوقائع إلى القوانين\". فلا يختلف القياس عن الاستقراء في الكيف، بل في الكم، ولذلك سنتجاوز القياس ونبحث في الاستقراء؛ لأن كل ما يُنقد على الاستقراء يصدق على القياس وليس العكس.","إذن الاستقراء يبتغي الحكم على حالةٍ لم نختبرها بناء على مجموعة من الحالات اختبرناها سلفًا، ولا مشكلة في الاستقراء كأداة في صناعة المعرفة، وقد اشتغل كثير من العلماء والفلاسفة على تعزيزه ومعالجة ثغراته، كالقرافي والشاطبي وديفيد هيوم ومحمد باقر الصدر وغيرهم الكثير. كما أنه لا يُشترط في الاستقراء أن يكون تامًا إلا في عالم المحسوسات، وهو هنا الاستقراء المنطقي الذي يتمثّل في \"الحكم على الكلي لوجود ذلك الحكم في جزئيات ذلك الكلي\". والاستقراء المنطقي إن لم يكن تامًا فهو \"لا يوجب علمًا\" كما يرى ابن سينا، وجزم في كتابه عيون الحكمة بأنه \"لا ثقة فيه أصلًا\".","أما الاستقراء في الإنسانيات فلا يُشترط فيه التمام، وقد شنّع دوركايم على من يشترط الاستقراء التام للوصول إلى الحكم الاجتماعي الدقيق، ويرى أن هذا الحرص \"ليس له من الطابع العلمي إلا مظهره فقط\"، حيث إنّه \"من الخطأ أن يعتقد المرء أن العلم لا يستطيع الكشف عن القوانين إلا بعد استقرائه لجميع الحالات الجزئية التي تعبر عنها هذه القوانين\".","ومع هذا التقدير للاستقراء كأداة لإنتاج المعرفة، فإن التعويل عليه لتعميم النظرية يواجه ثلاثة تحديات:","وهذا تمامًا ما ينطبق على الحقل السياسي، فعلى سبيل المثال لو تتبعنا خمس ثورات شعبية ناجحة، ووجدناها كلها تشترك في وجود قيادة مسبقة للثورة، فهل يمكن الحكم على أي ثورة قادمة بأنها لن تنجح إلا بوجود قيادة؟ لا نستطيع ذلك، فالأمر يتوقف على عوامل عديدة، منها طبيعة الحياة السياسية في المجتمع، ومستوى الوعي، وطبيعة الوحدات الاجتماعية وتوازناتها، وطبيعة الهويات الفرعية، ومدى تحقق الإجماع الوطني على مطلب الثورة، وغير ذلك. ولنفترض أننا استقرينا الدول المتوسطة فوجدنا أن ثمانين بالمئة منها تحل مشاكلها مع الدول الصغيرة المجاورة لها بالحل العسكري، فهذا لا يجعلنا نتوقع أبدًا أن تركيا ستحل خلافها مع أرمينيا حلًا عسكريًا، ولا أن إيران ستحل مشاكلها مع أذربيجان حلًا عسكريًا. الأمر يتوقف على طبيعة النظام السياسي وطبيعة صانع القرار، وطبيعة التحالفات الإقليمية والدولية لكلا الطرفين، وطبيعة التركيبة المجتمعية في كلا البلدين، وعلى غير ذلك من العوامل. وهكذا نجد أن الاستقراء وحده لا يملك مشروعية التعدية، وإنما لكل سياق معطياته المتفرّدة.","ومن المهم أخيرًا أن نقول إن الاستقراء إذا كان مبنيًا على حالات كثيرة مختلفة، فإنه يكون ذا جدوى مع الظواهر الشعبية أكثر منه مع الفاعلين؛ لأن احتمالات سلوك الجماعة أقل من احتمالات سلوك الفرد، فالجماعة عادةً تتصف بالعقلانية في ضوء التفسير المجتمعي للعقلانية، أما الأفراد فيمكن أن يذهبوا إلى خيارات لا نهائية، نتيجة اختلاف دوافعهم وطبائعهم النفسية وتصوراتهم لأنفسهم والآخرين."],"key":"وهكذا نجد أن الاستقراء وحده لا يملك مشروعية التعدية، وإنما لكل سياق معطياته المتفرّدة.","items":[{"h":"التحدي الأول: حرية الفاعل ونسبية الدافع","x":"يعود إلى مشكلتَي حرية الفاعل ونسبية الدافع اللتين تكلمنا عنهما توًّا، فالإنسان تختلف دوافعه واختياراته من سياق لآخر، وهذا يعني أن الظاهرة قد تتحقق شروطها ولا توجد، وقد لا تتحقق شروطها وتوجد؛ لأنها في النهاية مرتهنة لإرادة حرة."},{"h":"التحدي الثاني: صعوبة التفريق بين التلازم والتزامن","x":"فلنفترض أننا درسنا ستة نظم ديمقراطية واكتشفنا أنها جميعها تمتلك تنمية اقتصادية، فهل وجودهما معًا، أعني الديمقراطية والتنمية الاقتصادية، يدل على علاقة سببية تلازمية أم أنهما تزامنا معًا في هذه الحالات؟ فقد تكون التنمية عائدة إلى السياسات المالية والضريبية أو عائدة لموجهات ثقافية في المجتمع، وقد يكون الربط بينهما متكلّفًا يُعبّر عما ينبغي أن يكون عليه الحال، كما انتهى إلى ذلك الخبيران الأمريكيان لورن كارنر (Lorne Craner) وكينيث والك (Kenneth Wollack) بأنه يجب الربط بين الديمقراطية والتنمية حتى وإن لم يرتبطا واقعًا. هذه المعضلة، أعني معضلة التفريق بين العنصر الملازم والعنصر المتزامن، هي إشكال حقيقي يعرقل مشروع الأقيسة الاجتماعية التي يستند إليها الاستقراء، وإذا ثبت أنه عامل مؤثر، فما وزن هذا التأثير؟ هل يصل إلى أن يكون علة تتخلف الظاهرة بتخلفه أم أنه يسمح بوجودها ولكن بأشكال مختلفة؟"},{"h":"التحدي الثالث: شروط إنتاج الظاهرة","x":"لأن الاستقراء مبني على فرضية تساوي شروط إنتاج الظاهرة، لكن الظواهر الاجتماعية يصعب الجزم بشروط إنتاجها، وهذا ما جعل ابن خلدون يشنّع عليه قائلًا: \"ولا يقاس شيء من أحوال العمران على الآخر كما اشتبها في أمر واحد فلعلّهما اختلفا في أمور\". فهو يرى وجوب دراسة كل حالة كما هي في الواقع دون تعميم نظري مسبق؛ لأن كل حالة قد يتوافر فيها ما لا يتوافر في غيرها. وفي هذه الحالة يصدق ما قاله جيوفاني بوسينو (Giovanni Busino) في نقده لعلم الاجتماع، حين ذكر أن أزمة علم الاجتماع تكمن في أنه \"يبحث في مجتمع خاص عن حقيقة عامة، وفي التنوع عن التماثل، وفي الغيرية عن التشابه\"، وهذا ما يجعل علماء الاجتماع \"يتمنون، انطلاقًا من مجتمع خاص، إعطاءنا نظرية اجتماعية ذات صحة عامة\"."}]}],"examples":[{"who":"المجتمعات الخليجية (الطلاق)","x":"كقولنا: \"ازداد الطلاق في المجتمعات الخليجية\"، هذه ملاحظة وليست نظرية.","pg":18},{"who":"أمثال شعبية","x":"كقول الناس: \"كل ممنوع مرغوب\"، وقولهم: \"الصاحب ساحب\"، هذه معرفة تفسيرية تفسّر طوارئ السلوك الإنساني في حالة معينة، ولكنها قانون وليست نظرية","pg":19},{"who":"الطفل والمظلوم وحاكم الدولة الكبيرة الفقيرة","x":"هل الطفل الذي ينشأ في بيئة أسرية واجتماعية سيكون مجرمًا في المستقبل؟ ربما يكون كذلك، لكن ربما يفاجئنا ويكون عالـمًا صالحًا. والمرء الذي يتعرض لظلم وضغوط اجتماعية كبيرة لا ندري إن كان سيكون هشًا فيستسلم وينتحر؟ أو يكون صلبًا فيقاوم وينتصر؟ وحاكم الدولة الكبيرة الفقيرة حين يكتشف ثروات هائلة في دولة صغيرة تجاوره يمكن أن نقول سيغزوها، أو ينافسها، أو حتى نقول أنّه لن يبالي بها","pg":21},{"who":"شجرة الموز والبرتقال والبطيخ","x":"فشجرة الموز تنبت بطريقة محددة، وشجرة البرتقال تنبت بطريقة أخرى، وشجرة البطيخ بطريقة ثالثة، كل طريقة لها خطوات محددة، متى ما اختلّت الخطوات لم تنبت الشجرة، ومتى اكتملت تلك الخطوات لا يبقى للشجرة خيار في ألا تنبت وتنمو. لكن الإنسان ليس كالشجرة","pg":22},{"who":"ليونيد بريجينيف والاتحاد السوفيتي (غزو أفغانستان)","x":"قد نستمر في تحليل أسباب غزو الاتحاد السوفيتي لأفغانستان مستلهمين كل المعطيات الدولية والسياسية والأمنية والاقتصادية، ثم نكتشف أن الأمر لا علاقة له بكل تلك المسوغات العقلية، وإنما هي ردة فعل نفسية ناتجة عن حالة الإحباط النفسي التي مر بها رئيس الاتحاد السوفيتي ليونيد بريجينيف نتيجة رفض مجلس الشيوخ الأمريكي التصديق على معاهدة الحد من الأسلحة الاستراتيجية بين البلدين.","pg":24},{"who":"ستة نظم ديمقراطية، ولورن كارنر وكينيث والك","x":"فلنفترض أننا درسنا ستة نظم ديمقراطية واكتشفنا أنها جميعها تمتلك تنمية اقتصادية، فهل وجودهما معًا يدل على علاقة سببية تلازمية أم أنهما تزامنا معًا في هذه الحالات؟ ... كما انتهى إلى ذلك الخبيران الأمريكيان لورن كارنر وكينيث والك بأنه يجب الربط بين الديمقراطية والتنمية حتى وإن لم يرتبطا واقعًا.","pg":29},{"who":"خمس ثورات شعبية ناجحة","x":"لو تتبعنا خمس ثورات شعبية ناجحة، ووجدناها كلها تشترك في وجود قيادة مسبقة للثورة، فهل يمكن الحكم على أي ثورة قادمة بأنها لن تنجح إلا بوجود قيادة؟ لا نستطيع ذلك","pg":30},{"who":"تركيا وأرمينيا، وإيران وأذربيجان","x":"ولنفترض أننا استقرينا الدول المتوسطة فوجدنا أن ثمانين بالمئة منها تحل مشاكلها مع الدول الصغيرة المجاورة لها بالحل العسكري، فهذا لا يجعلنا نتوقع أبدًا أن تركيا ستحل خلافها مع أرمينيا حلًا عسكريًا، ولا أن إيران ستحل مشاكلها مع أذربيجان حلًا عسكريًا.","pg":31}],"quotes":[{"x":"لا يُستخدم لفظ ذو رنين في أحايين كثيرة كلفظ النظرية في العلوم الاجتماعية","by":"جورج هومانز","pg":18},{"x":"فعل لا نستطيع أن نفهم سببه، فعل عبثي لا يستطيع علم الاجتماع قول شيء حياله وما عليه إلا أن يستقيل","by":"بيير بورديو (في تعريف الفعل المجاني)","pg":23},{"x":"أهواء البشر هي عمومًا أقوى من عقولهم","by":"توماس هوبز","pg":23},{"x":"العقل ليس له سلطة إلا عند فئة قليلة من المثقفين، أما عموم الناس فتحكمها الأهواء","by":"جون ستيورات ميل","pg":24},{"x":"التوقع العقلاني","by":"أوغست كونت","pg":25},{"x":"فما من أحد إلا وهو راض عن الله سبحانه في كمال عقله، وأشدهم حماقة وأضعفهم عقلًا هو أفرحهم بكمال عقله","by":"أبو حامد الغزالي","pg":25},{"x":"العقل أعدل الأشياء توزعًا بين الناس؛ لأن كل فرد يعتقد أنه قد أوتي منه الكفاية","by":"رينيه ديكارت","pg":25},{"x":"العلاقات الدولية مملوءة باستخدام القياس التاريخي","by":"ديفيد باتريك (David P. Houghton)","pg":26},{"x":"ما يحصل للإنسان من التجارب والمعرفة بالحوادث وما تصير إليه عواقبها، فإنه لا يحدث أمر إلا قد تقدم هو أو نظيره فيزداد بذلك عقلًا","by":"ابن الأثير","pg":26},{"x":"انطلاق من الوقائع إلى القوانين","by":"روبير بلانشي (في تعريف الاستقراء)","pg":27},{"x":"الحكم على الكلي لوجود ذلك الحكم في جزئيات ذلك الكلي","by":"ابن سينا (في تعريف الاستقراء المنطقي)","pg":27},{"x":"لا يوجب علمًا","by":"ابن سينا (عن الاستقراء غير التام)","pg":28},{"x":"لا ثقة فيه أصلًا","by":"ابن سينا، عيون الحكمة","pg":28},{"x":"من الخطأ أن يعتقد المرء أن العلم لا يستطيع الكشف عن القوانين إلا بعد استقرائه لجميع الحالات الجزئية التي تعبر عنها هذه القوانين","by":"دوركايم","pg":28},{"x":"ولا يقاس شيء من أحوال العمران على الآخر كما اشتبها في أمر واحد فلعلّهما اختلفا في أمور","by":"ابن خلدون","pg":30},{"x":"يبحث في مجتمع خاص عن حقيقة عامة، وفي التنوع عن التماثل، وفي الغيرية عن التشابه","by":"جيوفاني بوسينو (عن أزمة علم الاجتماع)","pg":30}],"notes":["تسعى التمثلات الاجتماعية للالتفات إلى البعد الاجتماعي والثقافي الذي تغافلت عنه المدرسة الأمريكية الكلاسيكية المتمحورة حول البعد الفردي.","نظرية العلاج العقلاني الانفعالي تعود لألبرت إليس، وهي تقوم على أن الاضطرابات النفسية نتاج وجود أفكار غير عقلانية، وحل ذلك يكون في إحلال الأفكار العقلانية محلها.","بحسب Julian Lider تسعى النظرية العسكرية للإجابة عن ثلاثة أسئلة: ما القوة العسكرية؟ وكيف يمكن استعمالها بنجاح؟ وكيف يمكن الإعداد لاستعمالها بنجاح؟","مع استحضار المتغيرات الزمنية، فقد تكون النظرية مختبرة في زمن معين، ثم تطرأ متغيرات تتطلب إعادة هذا الاختبار.","الاستقراء لغة من القرو، وهو التتبع."],"quiz":[{"q":"كيف تعرّف الدراسة النظرية؟","o":["المعرفة التفسيرية المتحققة في سياق ما","المعرفة الوصفية العابرة للسياقات","كل فرضية لم تُختبر بعد","القانون الاجتماعي المطّرد"]},{"q":"ما العنصر الذي يميّز النظرية عن الفرضية؟","o":["التحقق، أي الاختبار","التفسير","السياق","التعميم"]},{"q":"متى تصبح النظرية «فرضية جيدة» فقط؟","o":["حين تنتقل من مجال النشأة إلى مجال الاستثمار","حين تُختبر في سياقها","حين تكون وصفية","حين يتبناها باحث مشهور"]},{"q":"ما الأسباب الثلاثة التي تحول دون تعميم النظرية؟","o":["حرية الفاعل، ونسبية الدافع، وأداة التعدية","قلة الباحثين، وضعف التمويل، وصعوبة اللغة","الوصف، والتفسير، والتقييم","المبادئ، والمصالح، والرغبات"]},{"q":"ما التحدي الذي يمثله مثال «ستة نظم ديمقراطية كلها تمتلك تنمية اقتصادية»؟","o":["صعوبة التفريق بين التلازم والتزامن","حرية الفاعل","تسرب التحيز","الطريقة الصفرية"]}],"sort":{"t":"ملاحظة أم نظرية أم قانون اجتماعي؟","s":"أمثلة المؤلف نفسه، صنّف كل عبارة بحسب جدوله.","bins":["ملاحظة","قانون اجتماعي","ليست نظرية: معرفة وصفية"],"items":[["ازداد الطلاق في المجتمعات الخليجية",0],["كل ممنوع مرغوب",1],["الصاحب ساحب",1],["الأنوميا: المجتمع في حالة سيولة المعايير",2]]}},{"k":"ch3","t":"المبحث الثالث: ما جدوى النظرية في التفسير والتنبؤ؟","q":"إذا كان الجواب لا يُعرف إلا بعد دراسة الظاهرة، فماذا تضيف النظرية المسبقة؟","sections":[{"t":"وظيفتا النظرية","p":["في المبحث السابق حاولنا مساءلة \"إمكان\" النظرية، وفي هذا المبحث سنسعى لمساءلة \"جدوى\" النظرية، فقد اعتاد الباحثون على تصدير أبحاثهم بالأطر النظرية التي تتضمن إجابة مسبقة يفترضون قدرتها التفسيرية لإشكال البحث، وبعضهم يتكلّف إحضار النظرية تكلّفًا لاعتقاده أن وجودها مؤشر على جديته الأكاديمية! ولا يخفى دور ما يسمى \"التقاليد الأكاديمية\" في إكراه الباحثين على هذا المسار.","والباحثون يستعملون النظريات لإنجاز وظيفتين أساسيتين:","فالنظرية إما أن نلجأ إليها لتفسير الظاهرة أو للتنبؤ بها، فهي إما تجيب على سؤال: لماذا حصل؟ أو: ماذا سيحصل؟ ولا جدال في أهمية هاتين الوظيفتين، ولكن الجدال في مدى إمكان أن تكون النظرية أداةً لتحقيقهما، وهذا ما ستحاول هذه الدراسة مناقشته في النقاط القادمة."],"items":[{"h":"الأولى","x":"وظيفة التفسير"},{"h":"الثانية","x":"وظيفة التنبؤ"}]},{"t":"أولًا: النظرية والجدوى التفسيرية","p":["المقصود بالتفسير الكشف عن أسباب الأفعال والظواهر الاجتماعية، والتفسير هو الذي يصنع المعنى للظاهرة، إذ الظاهرة بلا تفسير لا معنى لها، فحين يرتبط متغير بظاهرة دون وجود تفسير لارتباطه فإن هذا الارتباط يكون بلا معنى؛ كارتباط غياب الحرب في الدول الديمقراطية، فهذا لا يكون له معنى إلا حين يُفسّر هذا الارتباط وفقًا لنظرية السلام الديمقراطي مثلًا. فالتفسير مطلب أساس بلا شك، بل هو \"العملية المحورية في العلم\" على حد تعبير ناصيف نصار، وإذا كانت وظيفة التفسير مهمة وجوهرية، فهل تصلح النظرية للقيام بهذه المهمة؟","يتطلب الجواب على هذا السؤال أن نفهم طبيعة النظرية في العلوم الاجتماعية، والتي تختلف عن نظيرتها في العلوم الطبيعية، ففي النظرية الاجتماعية نبحث عادةً عن \"الصلاحية\"، أما في النظرية الطبيعية فالبحث عادةً عن \"الصحة\". فمثلًا كانت النظرية سابقًا تقوم على أن الأرض هي مركز الكون والأجرام السماوية تدور حولها، واستمرت هذه النظرية إلى أن جاء نيكولاس كوبرنيكوس بنظرية أخرى فبطلت النظرية الأولى. وكانت هناك نظرية الأثير المضيء التي تفترض أن موجات الضوء لا تنتقل إلا بوسيط يسمى الأثير المضيء، ثم بعد ذلك اكتشفوا خطأ هذه النظرية وتخلوا عنها.","لكن ليس هذا دأب العلوم الاجتماعية؛ لأن النظرية في العلوم الاجتماعية لا تكون خاطئة بقدر ما تكون قاصرة؛ والسبب في ذلك أنها انطلقت من واقع معين لاحظته وتحققت منه، وبالتالي هي صحيحة على الأقل بمقاس ذلك الواقع الذي تحققت منه (إن لم تتحقق منه فهي مجرد فرضية). ولكن لأن هذا الواقع غير مضمون التعميم في سياقات أخرى فإن النظرية ستبقى دائمًا بحاجة إلى دليل إضافي لإثبات صلاحيتها في سياق جديد.","ولأن مشكلة النظرية الاجتماعية في تأكيد صلاحيتها وتعدية مضمونها، فإن ذلك يجعلنا نتساءل عن جدوى اللجوء إليها للتفسير. بمعنى آخر: إذا كان الهدف من الاستعانة بالنظرية أن نستعملها في تفسير الظاهرة، فهذا أمر لا يمكن حسمه إلا بعد دراسة الظاهرة نفسها، فما الفائدة حينها من الاستعانة بها؟ وإذا قلنا إن الفائدة تتمثل في اختبار صلاحية النظرية فإن الإشكال سيبقى قائمًا، فلو اختبرت النظرية في حالة (أ) وتبين أنها صالحة للتفسير، فهذا لا يعني أني أستطيع آليًا استعمالها في تفسير حالة (ب)، بل يجب أن أتأكد من صلاحيتها، وهذا لن يتحقق إلا بعد البحث!","وهكذا يتبين أن جعل اختبار النظرية هدفًا ليس له جدوى كبيرة؛ لأنك لا تقيم هذا الاختبار مرةً واحدة وتكتفي كما هي النظرية في العلوم الطبيعية، بل يجب أن تعيده في كل دراسة لتكتشف الجواب بعد انتهاء البحث لا قبله. فلو أردت دراسة كيفية وصول صدام حسين إلى السلطة، بماذا ينفعني أن ألجأ إلى نظرية العصبية عند ابن خلدون كإطار نظري للدراسة؟ لأنه يمكن أن يكون صدام وصل إلى السلطة دون عصبية بالمفهوم الخلدوني، ويمكن أنه وصل مستعينًا بها، فإن كان وصل دونها عرفت أنها غير صالحة، وإن كان وصل بها عرفت حينها أنها صالحة، لكني لم أصل لذلك إلا بعد دراسة الموضوع!","ولو أردنا مثلًا تفسير النزعة الإجرامية لدى أحد صناع القرار فسنجد أنفسنا أمام نظريات كثيرة تدّعي التفسير، فهناك النظرية البيولوجية، التي ترى أن المجرم تعتريه إكراهات بيولوجية تدفعه للإجرام، وهناك النظرية النفسية الفرويدية التي ترى أن الإنسان يمتلك منذ مولده طاقة عدوانية، وهذه الطاقة العدوانية إذا لم تفرغ سوف تخرج بصور عدوانية كالقتل أو الاغتصاب، وتاليًا فإن الجرائم كلها مظاهر لانفجار الطاقة العدوانية. وهناك نظرية الإحباط العدوانية Frustration Aggression Theory، وهذه النظرية ترى أن المجرمين هم أناس تعرضوا لإحباطات متكررة، وتاليًا الدافع للجريمة هو التعبير عن ذلك الإحباط، وهناك نظرية التفسير الاجتماعي للسلوك الإجرامي التي ترى أن الجريمة نتيجة الضغوط الاجتماعية ونحوها.","فلو اعتمد الباحث على أي نظرية مسبقة فإنه في النهاية لن يحكم على الظاهرة إلا بعد دراستها، فماذا يستفيد الباحث من تأطير بحثه منذ البداية بإحدى هذه النظريات ما دام أنه لن يستطيع الوصول إلى التفسير الحقيقي إلا بعد دراسة الظاهرة؟ وقد ألف ديفيد باتريك كتابه ذائع الصيت \"علم النفس السياسي\" وحاول من خلاله مناقشة النظريتين الأساسيتين في تحليل موقف الفاعل السياسي، النظرية الموقفية والنظرية النزوعية، ثم بعد استعراض واسع لتطبيقاتهما ذكر أنه لا يمكن التعويل على أحدهما بنحو مطلق، فهناك أمثلة تبرهن النظرية الأولى، وأمثلة تبرهن النظرية الثانية، وبالتالي \"لن يخرج أحد رابحًا\" على حد تعبيره.","هكذا نكتشف ضآلة جدوى التعويل المسبق على النظرية في تفسير الظاهرة، وأننا بذلك نخدم النظريات أكثر مما تخدمنا.","وربما يُقال هنا: إن اللجوء إلى النظريات واختبارها مفيد لتحقيق التراكم المعرفي الذي لا يتحقق إلا بتكرار الاختبارات. هذا صحيح بلا شك، لكنه ليس مقصودنا في هذه الدراسة، فهذه الدراسة معنية بسؤال واحد، وهو علاقة النظرية في تحقيق وظيفة التفسير، أما إذا كان البحث يهدف لخدمة النظرية، فهذا هدف مشروع بلا شك، لكن كما ذكرنا توًّا أن نجاح النظرية في الاختبار في سياقٍ ما، لا يمنحها مشروعية تعميم مضمونها في سياقات أخرى إلا من خلال التأكد المسبق من توافر شروط نجاح النظرية."],"key":"وأننا بذلك نخدم النظريات أكثر مما تخدمنا."},{"t":"ثانيًا: النظرية والجدوى التنبؤية","p":["التنبؤ هو استشراف مآل الفعل الإنساني بناء على قواعد موضوعية. واشتراط وجود \"قواعد موضوعية\" هو الذي يميز التنبؤ العلمي عن سائر ضروب التنبؤات، كالتخمين والسحر والكهانة.","ولا شك أن الاستثمار الأقصى للعلوم يتمثّل في قدرتها على التنبؤ، ذلك أن \"المعرفة من أجل التنبؤ، والتنبؤ من أجل القدرة\". لكن طموح العلوم الاجتماعية للتنبؤ لا يساوي طموح العلوم الطبيعية؛ لأن الأخيرة نجحت في أن تصل بالتنبؤات إلى دوائر اليقين، أما العلوم الاجتماعية فقد تحمّست للوصول إلى التنبؤات اليقينية حين انخدعت بطموحات أوغست كونت الذي اغتر وانتشى بانتصارات العلوم الطبيعية على يد نيوتن ورفاقه فأرادها أن تزحف إلى أرض العلوم الاجتماعية، فقرر أنه يجب \"فهم الظواهر الاجتماعية دائمًا وكأنها خاضعة حتمًا لقوانين طبيعية حقيقية، مستوجبة بانتظام توقعًا عقلانيًا\". ولذلك كان يراهن على أنه سيبني السياسة على قواعد يقينية، بل إنه كان صريحًا في طموحه حين كان يريد تسمية علم الاجتماع بالفيزياء الاجتماعية لولا أن أحدًا سبقه بهذه التسمية فعدل عنها إلى \"علم الاجتماع\".","والواقع أن طموح العلوم الطبيعية لنقل تنبؤاتها الظنية إلى اليقين طموح مشروع بلا شك، وليس تاريخ تقدّم العلوم الطبيعية إلا تاريخ تحولات من الظن إلى اليقين، لكن لا يمكن للعلوم الاجتماعية أن تغار منها وتسعى سعيها، فالظن فيها سيبقى ظنًا إلى الأبد. والسر في ذلك، كما ذُكر سابقًا، أن العلوم الطبيعية تدرس الطبيعة، والطبيعة لها قوانين، والقوانين تنتج حتمية، ولذلك يمكن تفصيل التنبؤ على مقاس تلك الحتميّة. أما العلوم الاجتماعية فهي تدرس الإنسان، والإنسان له إرادة حرة، والحرية تقتضي تعدد الخيارات، وتعدد الاختيارات يربك التنبؤ. فمن يدرس الموضوعات الطبيعية يمكنه يومًا اكتشاف قوانينها والوصول إلى اليقين، لكن من يدرس الإنسان فستبقى حريته عائقًا جوهريًا في التنبؤ بمآلاته كما سبق إيضاح ذلك.","إذن التنبؤ الاجتماعي لا يساوي نظيره الطبيعي، وهذا لا ينفي إمكان التنبؤ، ولكن يثبت حدوده. وليس في ذلك منقصة، إذ ليس المطلوب من الباحث الاجتماعي أن يكون كاهنًا يقول: ستحصل ثورة فتحصل، ستندلعُ حرب فتندلع، وليس المطلوب منه أن يكون مثل عالم الأرصاد الذي يخبرنا بالدقيقة والثانية متى سيحصل الكسوف والخسوف. ليس المطلوب ذلك، ليس لأننا لا نريد، ولكن لأننا لا نستطيع. وإنما المطلوب أن ندرس الظاهرة دراسة \"موضوعية\" و\"علمية\" بما يضمن الاقتراب أكبر درجة ممكنة من النتيجة الصحيحة، وحين نقول \"موضوعية\" فهذا وصفٌ للباحث الذي لا يجعل تحيزاته المسبقة تحكم نتائج بحثه، وحين نقول \"علمية\" فهذا وصفٌ لعملية البحث التي تستبعد كل فرضية بلا دليل.","وإذا كان التنبؤ الاجتماعي ممكنًا، فهل النظرية هي أداته الأفضل؟ الواقع أن النظرية إذا لم يثبت جدواها في التفسير فلن يثبت جدواها في التنبؤ، بل عدم جدواها في التنبؤ أظهر وأجلى؛ لأن الاستعانة بها للتنبؤ قد يشوّش على معطيات الواقع بإجابتها المسبقة، لا سيما أنَّ صانع القرار قد يتصرف وفقًا لمحددات مختلفة عما تفترضه النظرية. وهذا الأمر ينطبق على معظم النظريات في حقل العلاقات الدولية، بما في ذلك النظريات الكبرى، فالواقعية التي تنطلق من فرضية أن صانع القرار يتحرك بحثًا عن المصلحة بآلية القوة، وأنه في سياق السعي إليها لا يلتفت إلى الأبعاد القانونية أو الأخلاقية، والليبرالية التي تستند إلى العقلانية وتفضيلات التبادل السلمي للمصالح واحترام القانون الدولي، والبنائية التي تعتمد على البعد الثقافي والهوياتي، لو أخذنا إحدى هذه النظريات وأردنا توظيفها في التنبؤ بموقف الرئيس بوتين من توسيع الصراع مع بولندا مثلًا، كيف سندرك تحقق ذلك في صانع القرار إلا بعد دراسة تاريخ صانع القرار وحدود قدراته؟","ولو أخذنا مثلًا نظرية توازن القوى التي تفترض أن الدول تسعى دائمًا لتحقيق توازن قوى مع خصومها، وأردنا التنبؤ بسلوك صانع القرار الأرميني بعد أن حصلت أذربيجان على أسلحة نوعية من تركيا بناءً على هذه النظرية، فإننا سوف نتوقع من صانع القرار الأرميني أن يدخل في سباق تسلح ليحقق توازن القوى، لكن قد لا يتحقق ذلك بالضرورة، فربما يكون صانع القرار الأرميني جبانًا فيفضّل التهدئة على التصعيد، وربما يخشى من الكُلفة المالية لسباق التسلّح فتؤثر على الحالة الاقتصادية لبلاده، وهو ما ينعكس بطبيعة الحال على حظوظه الانتخابية.","هكذا نجد أنفسنا، بسبب حرية الفاعل ونسبية دوافعه، غير قادرين على الاكتفاء بالنظرية في تحديد السيناريو المرجح، وإنما الأمر يتطلب دراسة سياقية للفاعل نفسه، وهو ما يقوم به النموذج الإرشادي الذي سنوضحه بعد قليل.","ويمكن تشبيه شأن النظرية بالذي يتنبأ بنتيجة المباراة قبل بدئها، فهو يرى مثلًا أن النتيجة سوف تنتهي بهزيمة برشلونة أمام ريال مدريد بهدفين مقابل لا شيء، بناء على تقييمه لأداء الفريقين في المباريات السابقة. الآن ما فائدة هذا التنبؤ؟ ليس له أي فائدة سوى إشباع فضول المتابع، أما النتيجة فلن تُعرف إلا من خلال متابعة المباراة إلى أن تنهيها صافرة الحكم. وهكذا هي النظرية إلى حدٍّ بعيد، تقدم تنبؤًا لا يمكن التحقق منه إلا من خلال دراسة الفاعل نفسه، أي بعد أن يكون الأمر تحصيل حاصل.","ولنأخذ مثالًا آخر، وهو نظرية المترقب (Prospect Theory) التي جاءت بها روز مكديرموت (Rose Mcdermott)، وطورها دانيال كانمان (Daniel Kahneman). حاولت هذه النظرية أن تجيب على سؤال: متى يخاطر صانع القرار؟ ترى هذه النظرية أن الأمر يتوقف على طبيعة وعي صانع القرار بوضعه، هل هو في وضع الخاسر أو في وضع الرابح؟ تفترض النظرية أن صانع القرار يبدأ بالمخاطرة حين يشعر بأنه في وضع الخاسر، أما حين يشعر بأنه في وضع الرابح فإنه سيتجنب المخاطرة. ويمكن أن نشبّه المسألة بوضع مدرب فريق كرة القدم، حين يكون فريقه خاسرًا فإن الأدعى في تلك الحالة أن يدفع بخطة هجومية متهورة، لأنه في وضع الخاسر، ولكن لو كان فائزًا أو متعادلًا فلن يكون متقبلًا للمخاطرة.","لكن هذه النظرية لا يبدو من النافع الانطلاق منها؛ لأنه ربما يكون صانع القرار في وضع الخاسر ومع ذلك لا يتقبل المخاطرة، إما لأنه أصلًا لا يعتقد أنه في وضع الخاسر، وإما أنه يخشى أن المخاطرة ستجلب له مزيدًا من الخسارة. فإذن حتى لو اتفقنا أن الشعور بوضع الخاسر يؤدي إلى المخاطرة فإن هذا لا يكفي؛ لأنه لا يجيب على سؤالين: كيف نجزم بأن صانع القرار مقتنع بأنه في وضع الخاسر؟ وما مستوى الخسارة الذي يدفع صانع القرار للمخاطرة؟ ما دام أن النظرية لا تمنح جوابًا على هذين السؤالين فإن الانطلاق منها لا يفيد شيئًا عمليًا.","وقد حاول جاك هايمانز (Jacques Hymans) أن يطور نظرية للتنبؤ على الأقل في مجال تطوير القدرات النووية، فرأى أن الذهاب باتجاه تطوير القدرات النووية لا يظهر إلا مع فئة واحدة من القادة، وهم القوميون التعارضيون Oppositional Nationalists، ويقصد بهم أولئك الذين يملكون رؤى متشددة تجاه خصومهم (منطق نحن وهم). ولذلك يرى أن إيران في عهد أحمدي نجاد وكوريا الشمالية في عهد كيم إيل سونغ ستملكان النووي. لكن هذه النظرية تغيّب تأثير القيود السياقية التي تعتري صانع القرار، ولذلك لم يصدق تنبؤه في حالة أحمدي نجاد، فصحيح أن نجاد يتصف بالقومية التعارضية في زمن رئاسته، لكن هذا لا يكفي لحسم خياراته إلا من خلال دراسته وفقًا للنموذج الإرشادي الذي سنقترحه في هذه الدراسة.","أما جورج هومانز فقد حاول أن يعالج الموضوع من خلال إضافة مقدمة كبرى Major Premise تضفي عليها خاصية التعميم، فمثلًا لو قلنا: لماذا لم يقرر ترمب إسقاط النظام الإيراني في حرب يونيو 2025؟ سيكون الجواب أن ذلك لم يكن من مصلحته في ذلك الوقت. هذه المسألة تبدو جزئية لا يُقاس عليها، وهنا يقترح جورج إضافة مقدمة كبرى سابقة، كأن نقول مثلًا: كل من لا يرى مصلحته راجحة في فعلٍ ما فإنه من المرجح ألا يفعله، والمقدمة الثانية: ترمب لم ير مصلحته راجحة في إسقاط النظام الإيراني، فإذن النتيجة أنه لن يسقطه.","لكن هذا المقترح لا يحل الأمر؛ لأن السؤال: وكيف نعرف أن ترمب يرى فيها مصلحة أو لا يرى! فلا شك أن الناس عمومًا تتبع مصالحها، هذا ليس اكتشافًا مدهشًا، لكن المعضلة أننا لا نعرف ما هي المصلحة بمنظور صناع القرار إلا بعد دراستهم فرادى، وهكذا نعود جميعًا إلى المربع الأول."],"key":"الواقع أن النظرية إذا لم يثبت جدواها في التفسير فلن يثبت جدواها في التنبؤ، بل عدم جدواها في التنبؤ أظهر وأجلى"}],"examples":[{"who":"الدول الديمقراطية ونظرية السلام الديمقراطي","x":"كارتباط غياب الحرب في الدول الديمقراطية، فهذا لا يكون له معنى إلا حين يُفسّر هذا الارتباط وفقًا لنظرية السلام الديمقراطي مثلًا.","pg":34},{"who":"نيكولاس كوبرنيكوس ومركزية الأرض","x":"كانت النظرية سابقًا تقوم على أن الأرض هي مركز الكون والأجرام السماوية تدور حولها، واستمرت هذه النظرية إلى أن جاء نيكولاس كوبرنيكوس بنظرية أخرى فبطلت النظرية الأولى.","pg":34},{"who":"نظرية الأثير المضيء","x":"وكانت هناك نظرية الأثير المضيء التي تفترض أن موجات الضوء لا تنتقل إلا بوسيط يسمى الأثير المضيء، ثم بعد ذلك اكتشفوا خطأ هذه النظرية وتخلوا عنها.","pg":34},{"who":"صدام حسين ونظرية العصبية عند ابن خلدون","x":"فلو أردت دراسة كيفية وصول صدام حسين إلى السلطة، بماذا ينفعني أن ألجأ إلى نظرية العصبية عند ابن خلدون كإطار نظري للدراسة؟","pg":36},{"who":"النزعة الإجرامية لدى أحد صناع القرار","x":"ولو أردنا مثلًا تفسير النزعة الإجرامية لدى أحد صناع القرار فسنجد أنفسنا أمام نظريات كثيرة تدّعي التفسير","pg":36},{"who":"ديفيد باتريك والنظريتان الموقفية والنزوعية","x":"ثم بعد استعراض واسع لتطبيقاتهما ذكر أنه لا يمكن التعويل على أحدهما بنحو مطلق، فهناك أمثلة تبرهن النظرية الأولى، وأمثلة تبرهن النظرية الثانية، وبالتالي \"لن يخرج أحد رابحًا\" على حد تعبيره.","pg":37},{"who":"أوغست كونت والفيزياء الاجتماعية","x":"بل إنه كان صريحًا في طموحه حين كان يريد تسمية علم الاجتماع بالفيزياء الاجتماعية لولا أن أحدًا سبقه بهذه التسمية فعدل عنها إلى \"علم الاجتماع\".","pg":39},{"who":"الكاهن وعالم الأرصاد","x":"إذ ليس المطلوب من الباحث الاجتماعي أن يكون كاهنًا يقول: ستحصل ثورة فتحصل، ستندلعُ حرب فتندلع، وليس المطلوب منه أن يكون مثل عالم الأرصاد الذي يخبرنا بالدقيقة والثانية متى سيحصل الكسوف والخسوف.","pg":39},{"who":"الرئيس بوتين وبولندا","x":"لو أخذنا إحدى هذه النظريات وأردنا توظيفها في التنبؤ بموقف الرئيس بوتين من توسيع الصراع مع بولندا مثلًا، كيف سندرك تحقق ذلك في صانع القرار إلا بعد دراسة تاريخ صانع القرار وحدود قدراته؟","pg":40},{"who":"أرمينيا وأذربيجان وتركيا","x":"وأردنا التنبؤ بسلوك صانع القرار الأرميني بعد أن حصلت أذربيجان على أسلحة نوعية من تركيا بناءً على هذه النظرية، فإننا سوف نتوقع من صانع القرار الأرميني أن يدخل في سباق تسلح ليحقق توازن القوى، لكن قد لا يتحقق ذلك بالضرورة","pg":41},{"who":"برشلونة وريال مدريد","x":"ويمكن تشبيه شأن النظرية بالذي يتنبأ بنتيجة المباراة قبل بدئها، فهو يرى مثلًا أن النتيجة سوف تنتهي بهزيمة برشلونة أمام ريال مدريد بهدفين مقابل لا شيء، بناء على تقييمه لأداء الفريقين في المباريات السابقة.","pg":41},{"who":"مدرب فريق كرة القدم","x":"حين يكون فريقه خاسرًا فإن الأدعى في تلك الحالة أن يدفع بخطة هجومية متهورة، لأنه في وضع الخاسر، ولكن لو كان فائزًا أو متعادلًا فلن يكون متقبلًا للمخاطرة.","pg":42},{"who":"إيران في عهد أحمدي نجاد وكوريا الشمالية في عهد كيم إيل سونغ","x":"ولذلك يرى أن إيران في عهد أحمدي نجاد وكوريا الشمالية في عهد كيم إيل سونغ ستملكان النووي. لكن هذه النظرية تغيّب تأثير القيود السياقية التي تعتري صانع القرار، ولذلك لم يصدق تنبؤه في حالة أحمدي نجاد","pg":43},{"who":"ترمب والنظام الإيراني (حرب يونيو 2025)","x":"لماذا لم يقرر ترمب إسقاط النظام الإيراني في حرب يونيو 2025؟ سيكون الجواب أن ذلك لم يكن من مصلحته في ذلك الوقت.","pg":44}],"quotes":[{"x":"العملية المحورية في العلم","by":"ناصيف نصار (عن التفسير)","pg":34},{"x":"لن يخرج أحد رابحًا","by":"ديفيد باتريك","pg":37},{"x":"المعرفة من أجل التنبؤ، والتنبؤ من أجل القدرة","by":"جان فرانسوا دورتيه (عن أوغست كونت)","pg":38},{"x":"فهم الظواهر الاجتماعية دائمًا وكأنها خاضعة حتمًا لقوانين طبيعية حقيقية، مستوجبة بانتظام توقعًا عقلانيًا","by":"أوغست كونت","pg":38},{"x":"يجب أن نلاحظ بشكل خاص أنه كان على نهضة العلوم الطبيعية المدهشة، وفي مقدمتها الكيمياء، أن تسعى تلقائيًا لأن توسّع المفهوم الأساس للقوانين الوضعية","by":"أوغست كونت","pg":38}],"notes":["فليس المقصود بالتفسير هنا تيار \"التفسيريون\" المعروف بين أوساط منظري العلاقات الدولية، وإنما المقصود التفسير كوظيفة عقلية، وبالتالي لا نفرق هنا بين Causes و Reasons."],"quiz":[{"q":"ما الوظيفتان الأساسيتان اللتان يستعمل الباحثون النظريات لإنجازهما؟","o":["التفسير والتنبؤ","الوصف والتقييم","الجمع والتصنيف","النقد والترجمة"]},{"q":"ما الفرق بين النظرية الاجتماعية والنظرية الطبيعية عند المؤلف؟","o":["في الاجتماعية نبحث عن «الصلاحية»، وفي الطبيعية عن «الصحة»","الاجتماعية يقينية، والطبيعية ظنية","لا فرق بينهما","الطبيعية لا تخطئ أبداً"]},{"q":"بماذا يشبّه المؤلف التنبؤ بالنظرية؟","o":["بمن يتنبأ بنتيجة المباراة قبل بدئها","بعالم الأرصاد الذي يحدد موعد الكسوف","بالطبيب الذي يشخّص المرض","بالمهندس الذي يرسم الخريطة"]},{"q":"ما خلاصة المؤلف في جدوى التعويل المسبق على النظرية في التفسير؟","o":["ضآلة الجدوى، وأننا نخدم النظريات أكثر مما تخدمنا","جدوى كبيرة لا يُستغنى عنها","جدواها في التفسير أعظم من البحث نفسه","لا يمكن البحث دونها"]}]},{"k":"ch4","t":"المبحث الرابع: النظريات إضافة مجانية أم إضافة مكلفة؟","q":"هل تكتفي النظرية المسبقة بألا تفيد، أم أنها تضر بالبحث أيضًا؟","sections":[{"t":"من جهد غير مثمر إلى إضافة مكلفة","p":["يمكن هنا أن نرفع سقف المرافعة ضد النظرية، ونقول إن النظرية حين تكون إطارًا مسبقًا للبحث فإنها لا تكون مجرد جهد غير مثمر فحسب، بل تكون إضافة مكلفة تضر بموضوعية البحث ودقته؛ لأن تأطير البحث بنظريةٍ ما يؤدي إلى إشكالين:"],"key":"بل تكون إضافة مكلفة تضر بموضوعية البحث ودقته"},{"t":"الإشكال الأول: استثارة التحيّز","p":["نعني باستثارة التحيّز الميل غير الواعي عند الباحث لإثبات منطقية اختياره للنظرية، وهي قريبة مما يسمى في علم النفس الانحياز التأكيدي Confirmation bias. فالباحث مثلًا قد يأخذ نظرية العصبية عند ابن خلدون لتفسير حالة السلطة في بلدٍ ما، ولكن حين يبدأ البحث يكتشف أن النظرية لا تمتلك الكفاءة التفسيرية، فيضطر حينها إلى التكلّف والتحوير في معطيات الواقع كي تتلاءم مع النظرية التي اختارها ليثبت جدواها وأهليتها. وهذا معتاد عند كثير من الباحثين. يقول ديفيد باتريك: \"البشر يميلون إلى تفسير الأدلة على نحو ينسجم مع اعتقاداتهم القائمة، وإلى إهمال المعلومات التي لا تنسجم مع تلك الاعتقادات\". وذكر كذلك أن \"هناك رغبة دائمة في جعل الدليل يناسب النظرية أكثر من الرغبة في ترك الدليل يمد النظرية بالدعم أو بالدحض دون تطويع\".","وهذا الأمر ليس خاصًا بالباحثين، بل حتى صناع القرار يرفضون في كثير من الأحيان المعلومات التي تأتي إليهم حين يجدونها تخالف قناعاتهم المسبقة؛ ولا يفلح الأمر إلا مع الإلحاح المتكرر.","إذن وجود النظرية مسبقًا قد يحول دون النظر بتجريد لمعطيات الواقع، فتصبح المعرفة الناشئة عن دراسة فاعلين آخرين آسرة له في فهم سلوك فاعل جديد لم تُسبق دراسته وفقًا لمحدداته الذاتية والسياقية."],"key":"نعني باستثارة التحيّز الميل غير الواعي عند الباحث لإثبات منطقية اختياره للنظرية"},{"t":"الإشكال الثاني: تسرّب التحيّز","p":["لا تكاد تخلو نظرية من تحيزاتها المستبطنة، سواء على المستوى الوصفي أو التفسيري أو المعياري، وهذه نتيجة طبيعية لمنطق النسبية الذي يحيط بالنظرية، فهي بالضرورة ناشئة عن واقع معين، وثقافة معينة. وهذا التحيز الذي تستبطنه النظرية ثمة إمكانيّة لتسربه لوعي الباحث، لا سيما إن كانت النظرية ذات هالة في مجالها بما يؤثر سلبًا على استقلال الباحث وموضوعيته في التعامل معها. وقد تحدث ألفن جولدنر (Alvin Gouldner) عمّا يسميه \"الافتراضات الضمنية\" background assumptions التي لا مفر منها، \"فسواء أحب علماء الاجتماع ذلك أم كرهوه، عرفوه أم جهلوه، ففي النهاية سوف ينظمون بحوثهم بالنظر إلى افتراضاتهم المسبقة\".","وتزداد احتمالية تسرّب التحيّز حين نتذكر أن \"التّقليد عريق في الآدميّين وسليل\" على حد تعبير ابن خلدون. ولذلك نجد كثيرًا من الباحثين يستعير النظرية كما هي، لا يحمل هم مساءلتها ومفاتشتها بقدر ما يحمل هم تطبيقها وتمثّلها، وإذا كانت الحاسة النقديّة ضعيفة في المجمل، فإن ذلك أدعى لتسرب تحيزات النظريات دون شعور الباحثين بها.","فعلى سبيل المثال يمكن أن يعتمد الباحث على نظرية مارك بلوخ (Marc Bloch) التي مفادها أن العادات والتقاليد تصنع وهم الاستمرار من أجل إخفاء التغير الاجتماعي، فقد يأخذها الباحث ويؤمن بها وتهيمن على وعيه دون أن يشعر، في حين واقعه يسير على العكس، فإذا كان مارك يرى أن العادات تخلق وهم الاستمرار لتخفي التغيرات الاجتماعية، فربما يكون المجتمع الخليجي مثلًا يسير عكس ذلك، بأن يخلق وهم التغير الاجتماعي ليخفي استمرار تمسكه بالعادات والتقاليد!","ويتعزز هذا المنحى إذا أخذنا بالاعتبار فكرة \"العقلانية المحدودة\" وكذلك فكرة \"سلوك الاستكفاء\" اللتين نظّر لهما عالم النفس هربرت سيمون (Herbert Simon)، وخلاصتهما أن الإنسان حين تتكاثر أمامه الخيارات فإنه لا يبدي النظر الكافي فيها جميعًا، وإنما يكتفي عادةً بالموازنة بين خيارين أو ثلاثة، وذلك في إطار عقلانيته المحدودة بطبيعة الحال."],"key":"لا تكاد تخلو نظرية من تحيزاتها المستبطنة، سواء على المستوى الوصفي أو التفسيري أو المعياري"},{"t":"الخلاصة: وعي مزيف عن الواقع","p":["إذن، يمكن القول إن وجود النظرية بشكل مسبق يخلق مشكلتَي استثارة التحيّز وتسرّبه، وهذا ما يجعل النظرية ليست مجرد إضافة مجانية فحسب، بل إضافة مكلفة ربما تصل كلفتها إلى حجب وعي الباحث عن الواقع، فلا يراه كما هو، بل كما خيّلت له النظرية، وهو بطبيعة الحال يؤدي إلى نشوء وعي مزيف عن الواقع."],"key":"فلا يراه كما هو، بل كما خيّلت له النظرية، وهو بطبيعة الحال يؤدي إلى نشوء وعي مزيف عن الواقع."}],"examples":[{"who":"باحث يفسر السلطة في بلد ما بنظرية العصبية عند ابن خلدون","x":"فالباحث مثلًا قد يأخذ نظرية العصبية عند ابن خلدون لتفسير حالة السلطة في بلدٍ ما، ولكن حين يبدأ البحث يكتشف أن النظرية لا تمتلك الكفاءة التفسيرية، فيضطر حينها إلى التكلّف والتحوير في معطيات الواقع كي تتلاءم مع النظرية التي اختارها ليثبت جدواها وأهليتها.","pg":45},{"who":"صناع القرار والمعلومات المخالفة","x":"بل حتى صناع القرار يرفضون في كثير من الأحيان المعلومات التي تأتي إليهم حين يجدونها تخالف قناعاتهم المسبقة؛ ولا يفلح الأمر إلا مع الإلحاح المتكرر.","pg":46},{"who":"مارك بلوخ والمجتمع الخليجي","x":"فإذا كان مارك يرى أن العادات تخلق وهم الاستمرار لتخفي التغيرات الاجتماعية، فربما يكون المجتمع الخليجي مثلًا يسير عكس ذلك، بأن يخلق وهم التغير الاجتماعي ليخفي استمرار تمسكه بالعادات والتقاليد!","pg":48}],"quotes":[{"x":"البشر يميلون إلى تفسير الأدلة على نحو ينسجم مع اعتقاداتهم القائمة، وإلى إهمال المعلومات التي لا تنسجم مع تلك الاعتقادات","by":"ديفيد باتريك","pg":45},{"x":"هناك رغبة دائمة في جعل الدليل يناسب النظرية أكثر من الرغبة في ترك الدليل يمد النظرية بالدعم أو بالدحض دون تطويع","by":"ديفيد باتريك","pg":46},{"x":"فسواء أحب علماء الاجتماع ذلك أم كرهوه، عرفوه أم جهلوه، ففي النهاية سوف ينظمون بحوثهم بالنظر إلى افتراضاتهم المسبقة","by":"ألفن جولدنر","pg":47},{"x":"التّقليد عريق في الآدميّين وسليل","by":"ابن خلدون","pg":47},{"x":"النزعة إلى جمع المعلومات أو تفسيرها بشكل انتقائي يؤكد المعتقدات أو التوقعات أو الفرضيات السابقة","by":"الجمعية الأمريكية لعلم النفس (تعريف الانحياز التأكيدي)","pg":45}],"notes":["تعرّف الجمعية الأمريكية لعلم النفس الانحياز التأكيدي بأنّه: \"النزعة إلى جمع المعلومات أو تفسيرها بشكل انتقائي يؤكد المعتقدات أو التوقعات أو الفرضيات السابقة\".","جدير بالذكر في هذا السياق الإشارة إلى محاولة نقدية أجراها مجموعة من الباحثين في مركز ابن خلدون للاستدراك على بعض المقولات الخلدونية المتعلقة بنشأة الدولة وسقوطها، وذلك من خلال تطوير إطار نظريّ يحتمل التحولات المحلية والعالمية الطارئة على الدولة العربية. ينظر: التيجاني عبد القادر، وآخرون. استدراكات على النموذج الخلدوني: تطبيق على الحالتين اليمنية والتونسية. مركز ابن خلدون للعلوم الإنسانية والاجتماعية. 2024."],"quiz":[{"q":"ما الإشكالان اللذان يسببهما تأطير البحث بنظرية مسبقة؟","o":["استثارة التحيز وتسرّبه","حرية الفاعل ونسبية الدافع","الوصف والتفسير","القياس والاستقراء"]},{"q":"استثارة التحيز قريبة مما يسمى في علم النفس:","o":["الانحياز التأكيدي","العقلانية المحدودة","سلوك الاستكفاء","التمثلات الاجتماعية"]},{"q":"ما الذي قد تصل إليه كلفة النظرية المسبقة؟","o":["حجب وعي الباحث عن الواقع ونشوء وعي مزيف","زيادة دقة البحث","تقليل التحيز","تسريع الوصول إلى اليقين"]},{"q":"ما المثال الذي ضربه المؤلف عن نظرية مارك بلوخ والمجتمع الخليجي؟","o":["ربما يخلق المجتمع الخليجي وهم التغير ليخفي استمرار تمسكه بالعادات","العادات تمنع كل تغير في المجتمع الخليجي","المجتمع الخليجي لا عادات فيه","نظرية بلوخ تنطبق تماماً على الخليج"]}]},{"k":"ch5","t":"المبحث الخامس: من التفكير بالنظرية إلى التفكير بالنموذج","q":"كيف نتنبأ بقرار إنسان؟ بالسؤال عن إرادته وقدرته وطريقته","sections":[{"t":"النظرية ليست أداة للتفكير","p":["ربما بدا الحديث السابق وكأنه إعلان لقطيعة تامة مع النظريات، ولذلك ثمة حاجة هنا للمسارعة بدفع هذا الوهم، فليس الغرض نفي قيمة النظرية وجدواها، لكن القصد مساءلة التموضع السليم للنظرية في نظام البحث وخصوصًا في السياق السياسي الدولي. فالنظرية بلا شك لها قيمة ظاهرة تتجلى في توسيع مدارك الباحث ومساحات تفكيره، هذا أمر لا يمكن إنكاره، لكن ما هو محل الإنكار أن تصير النظرية أداةً للتفكير، ونعني بأداة التفكير أن يختارها الباحث إطارًا نظريًا مسبقًا للتفكير في محل البحث؛ فينظر للواقع من خلالها وبها.","والذي يمنع النظرية من أن تكون أداة للتفكير هو أن أداة التفكير يجب أن يتوافر فيها عنصران:","وهذان الشرطان لا يتوافران في النظرية التي تكون عادةً متحيزة ونسبية؛ أما تحيزها فلأجل الافتراضات الضمنية عند الباحثين، وأما نسبيتها فلأجل اختلاف المعطيات السياقية، ولذلك لا يصح أن تكون النظرية أداةً للتفكير يرى الباحث معطيات واقعه من خلالها، فقد تجعله يرى الأشياء خلاف ما هي عليه، وبذلك تكون سببًا في نشوء وعي مزيف. فمثلًا لو رأينا حالة التبعية العربية للمنظومة الغربية، فهنا يمكن الاتكاء على المقولة التفسيرية لابن خلدون بأن المغلوب مولع بالغالب، لكن هذا قد لا يعكس الواقع، فقد تكون هناك أسباب أخرى أمنية أو اجتماعية أو سياسية أدت إلى ذلك.","أما الذين يقولون إنه لا بحث بلا نظريات، ولا بد من نظرية تؤطر البحث، فهؤلاء في الحقيقة يخلطون بين النظرية والمنهج، فصحيح أنه لا بحث إلا بمنهج، ولكن ليس صحيحًا أنه لا بحث إلا بنظرية، بل المنهج يقتضي أن يكون البحث بلا نظرية مسبقة حتى يستقيم في إصدار نتائجه دون الوقوع في فخ التحيزات الضمنية.","وإذا كانت النظرية لا تصلح أن تكون أداةً للتفكير؛ فما الذي يمكن أن يعوّل عليه الباحث في الحقل كأداة للتفكير؟","هذا يقودنا إلى الفكرة التي نقترحها في هذه الدراسة وهي فكرة النموذج الإرشادي كأداة تفكير بديلة وظيفيًا عن النظرية، فالفرضية التي تتبناها هذه الدراسة أن التنبؤ والتفسير لا يحتاج إلى نظرية بقدر احتياجه إلى نموذج، والمقصود بالنموذج هو دراسة شروط إنتاج سلوك صانع القرار من خلال البحث في إرادته وقدراته وطرائقه."],"key":"فهؤلاء في الحقيقة يخلطون بين النظرية والمنهج","items":[{"h":"الأول: الإطلاق","x":"بألا تكون متحيّزة لفرضيات مسبقة."},{"h":"الثاني: العموم","x":"بألا تكون خاصة بسياق معين."}]},{"t":"النموذج الإرشادي: الإرادة والقدرة والطريقة","p":["لتوضيح ذلك نقول إذا عدنا إلى طبيعة القرار الإنساني سنجده نتيجة جدلية بين ثلاثة أمور: الإرادة والقدرة والطريقة، فالإنسان قد يريد فعل شيء ما لكنه لا يستطيعه، وقد يستطيعه لكنه لا يريده، فهو إما مقتدر بلا إرادة أو مريد بلا قدرة، ولا يتحقق الفعل إلا باجتماع الأمرين، وإذا اجتمع الأمران فإما أن يسعى للمطلوب بطريقة جذرية أو تراكمية. فإذا أردنا التنبؤ بموقف صانع القرار فإن علينا أن نفهم أولًا ماذا يريد، وما محددات تفكيره وأولوياته، ثم بعد ذلك نبحث في طبيعة قدراته لتحقيق ما يريد، ثم أخيرًا نبحث في الكيفية التي يعتاد على تحقيق أهدافه من خلالها.","وإذا كان القرار الإنساني هو نتيجة ثلاثية الإرادة والقدرة والطريقة، فإن دراسة موجهات الإرادة ومستويات القدرة وأنماط الأساليب ستجعلنا نصل إلى أقرب نقطة ممكنة لاستشراف القرار الإنساني."],"key":"والمقصود بالنموذج هو دراسة شروط إنتاج سلوك صانع القرار من خلال البحث في إرادته وقدراته وطرائقه.","table":{"head":["صانع القرار","الإرادة (Will)","القدرة (Ability)","الطريقة (Approch)"],"rows":[["محددات النموذج الإرشادي","المبادئ، المصالح، الرغبات","الذاتية، الداخلية، الخارجية","الصفرية، التراكمية"]]}},{"t":"الركيزة الأولى: إرادة الفاعل","p":["تكمن الركيزة الأولى في النموذج الإرشادي في إرادة الفاعل محل الدراسة، ويمكن إرجاع إرادة الفاعل إلى ثلاثة محددات:","والرغبة تختلف عن المصلحة، فالرغبة نتاج عاطفة، والمصلحة نتاج تعقّل. كما أن المرء يبتغي من المصلحة منفعة مباشرة، أما الرغبات فغايتها إرضاء العاطفة بصرف النظر عن تحقق الفائدة والنفع. فمثلًا يمكن لرئيس دولة أن يرفض الوقوف مع دولة أخرى، مع أن مبادئه ومصالحه تقتضي ذلك، وإذا فتشنا عن السبب سنجده يعود إلى كراهية شخصية بينه وبين رئيس تلك الدولة. والعكس كذلك صحيح، فقد يقف رئيس دولة مع دولة أخرى لا لأجل مصلحة الدولة أو مبادئها، بل لأجل قوة العلاقة الشخصية بين الرئيسين.","وأخيرًا تعد الرغبة مفهومًا بسيطًا، في حين المصلحة مفهوم مركب، فالرغبة واضحة، إما حب أو كره، زهد أو طمع، أما المصلحة فهي مفهوم مركب متشابك، ولذلك يحار المرء نفسه أحيانًا في فهم مصلحته، لكنه لا يحار في فهم رغبته.","هذه هي المحددات الثلاثة للإرادة الإنسانية، فكل قرار إنساني يدور في فلك هذا المثلث ولا بد، وإنما يختلف الناس في ترتيب هذه الثلاثية، فمن الناس من يقدم مبادئه على ما سواها، ومنهم من يقدم مصالحه، ومنهم من يقدم رغباته، ولأن الإنسان كائن مخيّر لا مسيّر، فقد يعيد ترتيب هذه الثلاثية في لحظات مفاجئة."],"key":"ولذلك ليس دقيقًا القول إن السياسة مبنية على المصالح وحدها، وإنما هي مزيج بين مصالح ورغبات ومبادئ.","items":[{"h":"المحدد الأول: المبادئ Principles","x":"والمقصود بها الأفكار المعيارية التي يؤمن بها الإنسان عند تحديد موقفه من الخير والشر. والمبادئ ليست بالوزن ذاته دائمًا، فبعض المبادئ أثقل وزنًا من غيرها، وبعضها أثقل في مرحلة دون غيرها، وهلم جرا."},{"h":"المحدد الثاني: المصالح Interests","x":"والمقصود بالمصلحة كل ما يحقق نفعًا غير متعلق بالمبادئ، وهي حاضرة على ثلاثة مستويات؛ مستوى صانع القرار نفسه؛ كتحقيقه بعض المكتسبات لأغراض انتخابية، ومستوى الدولة، كالدخول في الحرب لأجل نهب الثروات، ومستوى إقليمي/دولي، كأن تتوافق مجموعة من الدول على إبقاء حالة الحرب مشتعلة في منطقة ما لأسباب متعلقة بالمصالح أو المبادئ أو كليهما. وليس بالضرورة أن تتعارض المبادئ والمصالح، فقد يقتضي المبدأ أحيانًا ما تقتضيه المصلحة."},{"h":"المحدد الثالث: الرغبات Desires","x":"وهي مطلوبات المرء المرتبطة بعواطفه، كالكره والحب والطمع والخوف والحسد وغيرها من ضروب العاطفة. والرغبة محدد مهم في فهم السلوك الإنساني عمومًا، والسلوك الدولي على وجه الخصوص؛ وهو محدد يكاد يُغفل عنه في أدبيات حقل العلاقات الدولية، إذ يكثر التركيز على ثنائية المبادئ والمصالح باعتبارهما المحددين الوحيدين في صناعة القرار الدولي. وهذا الحصر غير دقيق، إذ يخبرنا التاريخ السياسي عن جنوح كثير من صناع القرار إلى خيارات تخالف مبادئهم ومصالحهم لأجل تحقيق رغباتهم، ولذلك ليس دقيقًا القول إن السياسة مبنية على المصالح وحدها، وإنما هي مزيج بين مصالح ورغبات ومبادئ."}],"table":{"head":["الرغبة","المصلحة"],"rows":[["شخصية","قد تكون شخصية أو حزبية أو وطنية"],["ليس بالضرورة نافعة","نافعة بالضرورة"],["بسيطة وواضحة","مركبة ومعقدة"],["وجدانية","عقلية"]]}},{"t":"طرق الكشف عن إرادة صانع القرار","p":["المحددات الثلاثة التي ذكرناها توًّا يجب أن تُفهم في إطار \"تصوّرات\" صانع القرار، ونعني بالتصورات القناعات الكامنة في وعي الفرد والتي تنتج أفكاره وممارساته وتحدد كيفية فهمه للأمور، فالفرد لديه تصورات تجاه كل ما في الحياة، وهذه التصورات هي التي تشكّل كل معتقدات الفرد وممارساته، ولذلك يقول دوركايم إن \"الإنسان من وجهة النظر الفيزيائية ليس أكثر من منظومة خلايا، ومن جهة النظر العقلية ليس أكثر من منظومة تصورات\".","ولذلك يجب أولًا التعرّف على تصورات صانع القرار، لأنها هي التي تحدد طبيعة نظر صانع القرار لكل شيء، فلا يكفي أن ندرك أن صانع القرار يؤمن بالمبدأ الفلاني، بل يجب أن نعرف كيف يتصور هذا المبدأ؟ ولا يكفي أن نقول صانع القرار الفلاني يتبع مصلحته، إذ لا يحيلنا ذلك إلى شيء ما لم ندرك تصوراته للمصلحة. وكذلك لا بد من معرفة كيف يتصور صانع القرار النظامَ الدولي؟ وكيف يتصور تموضع دولته في بيئتها الإقليمية والدولية؟ وما تصوّره تجاه القضايا الكبرى في الأخلاق والدين والتاريخ والسياسة وغيرها؟ كل هذه الأسئلة وغيرها ينبغي أخذها بعين الاعتبار لاستكشاف تصورات صانع القرار.","لكن السؤال هنا: كيف ندرك موقف صانع القرار من هذه الثلاثية؟ إذ لا يبدو مفيدًا اللجوء إلى النظريات التقليدية، فهي وإن كانت تقسّم الناس فعلًا، إلا أنّها لا تخبرك أي الأقسام ينتمي إليها صانع القرار الذي تريد التنبؤ بقراره. فالواقعية والليبرالية مثلًا تتحدثان عن صنفين في آليات استيفاء المصالح، هناك صنف يهتم بالقانون الدولي والمبادئ العامة، وهناك صنف آخر يؤمن بفوضوية النظام الدولي وتاليًا يعوّل على القوة، لكننا لن نعرف أن صانع القرار يتبع أي النظريتين إلا بعد دراسة صانع القرار نفسه، وهكذا نكتشف أن النظرية لا تمنحنا أي امتياز فارق.","والواقع أن الكشف عن إرادة صانع القرار يمكن أن يتحقق من خلال الطرق الأربعة الآتية:","هذه هي الطرق الأربع التي يمكن من خلالها فهم شخصية صانع القرار، ولا شك أن الطريقة الأولى هي الأفضل لكونها مباشرة، لكنها تواجه مشكلة الإتاحة The problem of access، إذ ليس من المتيسّر لعموم الباحثين الوصول إلى معلومات من المقرّبين لصانع القرار، ولذلك يعوّل الباحثون في التنبؤات السياسية على الطريقة الثانية. فمثلًا حين نتتبع التراكم التاريخي لسلوك صانع القرار الإيراني سنجده لا يميل أبدًا إلى المواجهة العسكرية المباشرة حتى مع ضعف الطرف الآخر، وإنما يفضل دائمًا الضربات الموضعية، إن اضطر لذلك، أو التحرك من خلال وكلائه وحلفائه، لكنه في كل الأحوال لا يفضل أبدًا أن تكون الدولة الإيرانية نفسها جزءًا من أي مواجهة مباشرة. أما الطريقة الثالثة فهي الأضعف، وقد تجاوزتها مدارس علم النفس الحديثة، وقد تكون الطريقة الرابعة الحل الأخير في ظل غياب المعلومات والرصيد التاريخي."],"key":"ولذلك يجب أولًا التعرّف على تصورات صانع القرار، لأنها هي التي تحدد طبيعة نظر صانع القرار لكل شيء","items":[{"h":"الطريقة الأولى: المعلومات المباشرة","x":"بأن يحصل الباحث على معلومات مباشرة من المحيطين بصانع القرار مما يكشف عن طبيعة شخصيته وتصوراته، وموقفه من المحددات الثلاثة وكيفية فهمه لها."},{"h":"الطريقة الثانية: التراكم التاريخي لصانع القرار","x":"وتتمثل بتتبع تاريخ سلوك صانع القرار تجاه الأحداث المماثلة لاستنباط طبيعة ترتيبه للمحددات الثلاثة، وتحليل مضمون خطاباته وحواراته المباشرة."},{"h":"الطريقة الثالثة: المدخل الفرويدي","x":"والذي يعوّل على ما يسمى السيرة النفسية (Psychobiography) أو التاريخ النفسي (Psychohistory) لصانع القرار؛ فيتتبع الباحث هنا السيرة النفسية لصانع القرار منذ طفولته، وينظر في المؤثرات الأساسية ليفهم من خلالها طبيعة محددات تفكيره؛ فكما يقول هارولد لاسويل: \"العلوم السياسية من دون سير ذاتية هي نوع من التحنيط\"."},{"h":"الطريقة الرابعة: التفهّم Empathy","x":"بأن يتقمّص الباحث موقف صانع القرار ويضع نفسه موضعه، فيفكر في كيفية التصرّف بحسب طبيعة الموقف وخصائصه. فلنفترض مثلًا أن أوكرانيا كانت تسعى للانضمام إلى الناتو، ماذا ينبغي أن يفعل صانع القرار الروسي في هذه الحالة؟ هنا يضع الباحث نفسه مكان صانع القرار الروسي ويستظهر السيناريوهات المحتملة."}]},{"t":"الركيزة الثانية: قدرة الفاعل","p":["ونعني بالقدرة مجموع إمكانات صانع القرار التي تسمح بتحقيق مراده، ويمكن تقسيم القدرة من هذه الزاوية إلى ثلاثة أنواع:","هذه مستويات القدرة الثلاثة التي تساعدنا على التنبؤ باتجاه صانع القرار في قضيةٍ ما، ولا شك أن استيعاب هذه القدرات يحتاج إلى معرفة مركبة، فمثلًا استيعاب القدرة الذاتية عند صانع القرار يتطلب متابعة لشخصيته والمواقف التي يتعرض لها، والمعلومات التي تُرصد عنه، وأما القدرة الداخلية فتُعرف من خلال دراسة طبيعة النظام السياسي وأوزان الفاعلين السياسيين والهويات المجتمعية الفرعية وغير ذلك، وأما القدرة الدولية فتتطلب معرفة بالنظام الإقليمي والحلفاء الدوليين والقانون الدولي ونحو ذلك.","ولا يوجد تلازم بين هذه القدرات الثلاث، فقد يكون صانع القرار قويًا في المجتمع الدولي ولا يبالي بالتحديات الدولية لكنه عاجز في الدائرة الداخلية، إما بسبب طبيعة النظام السياسي أو بسبب مهددات أخرى. وقد يمتلك صانع القرار قدرة داخلية ودولية على اتخاذ القرار لكن طبيعته الشخصية التي تميل إلى التردد والجبن تحول دون ذلك.","لكن في كل الأحوال يجب أن تؤخذ هذه المستويات الثلاثة وحدةً واحدة، ولا يصح الاكتفاء بأحدها في صناعة التنبؤ، وهذا الخطأ يقع فيه بعض الباحثين حين يختزل تحليل قدرات صانع القرار في أحد المستويات الثلاثة، فيأتي عند صانع قرار مستبد فيعتقد أنه قادر على فعل ما يشاء، لكنه لا ينتبه لضعف قدراته النفسية أو وجود قيود مجتمعية وثقافية تمنعه من فعل ما يريد."],"key":"لكن في كل الأحوال يجب أن تؤخذ هذه المستويات الثلاثة وحدةً واحدة، ولا يصح الاكتفاء بأحدها في صناعة التنبؤ","items":[{"h":"القدرة الذاتية","x":"وهي تشمل القدرات النفسية والعقلية في شخصية صانع القرار، فمن ناحية قد يتسم صانع القرار بالشجاعة أو الجبن، الأنفة أو الذل، الرضا أو الطمع، الصبر أو الجزع. ومن ناحية أخرى، قد يتصف بالذكاء أو الحماقة، الحكمة أو الجهالة، الحذر أو التهور، الانفتاح أو الانغلاق (الدوغمائية) وغير ذلك من الصفات التي تؤثر في صناعة القرار الإنساني. فربما يمتلك صانع القرار كل القدرات الداخلية والخارجية الكافية لردع دولةٍ ما عن تجاوزها، لكنه يتصف بالجُبن والتردد مما يجعلنا نميل إلى أنه لن يتحرك تجاه هذا التجاوز."},{"h":"القدرة الداخلية","x":"وهذه متعلقة بمقدرة صانع القرار على تجاوز العوائق الداخلية، كطبيعة النظام السياسي، وعقيدة الدولة، وهوية المجتمع، وتوازنات الفاعلين السياسيين. فمثلًا قد يريد الرئيس الأمريكي عقد اتفاقية مع إيران، لكن لديه عائق داخلي يتمثل في الأغلبية البرلمانية، أو ربما يريد الرئيس إيقاف نزاع حربي في إحدى دول العالم، لكن ضغط شركات الأسلحة يمنعه من اتخاذ هذا القرار. والقدرة الداخلية ليست مهمة في النظام الديمقراطي فحسب، بل حتى في النظم غير الديمقراطية، فمثلًا قد يرغب صانع قرار في نظام شمولي أن يُشعل نزاعًا مع دولة أخرى، لكن يخشى من تأثير قبيلة كبيرة في مجتمعه، أو طائفة أو فئة عرقية أو غير ذلك."},{"h":"القدرة الخارجية","x":"وهذه متعلقة بقدرة صانع القرار على تجاوز العوائق الخارجية، كمصالح القوى الكبرى أو القانون الدولي أو طبيعة قواعد الاشتباك الإقليمي ونحو ذلك. فمثلًا يمكن أن تكون تركيا قادرة ذاتيًا وداخليًا على توجيه ضربة لليونان في بعض الجزر المتنازع عليها، لكن تركيا تدرك أن ذلك يؤدي إلى توريطها مع الولايات المتحدة أو الاتحاد الأوروبي أو على الأقل تهديدها بالفصل السابع في دوائر مجلس الأمن، فتحجم عن ذلك مع امتلاكها القدرة الذاتية والداخلية."}]},{"t":"الركيزة الثالثة: طريقة الفاعل","p":["قد يمتلك صانعو القرار الهدف ذاته، لكن نجد اختلافًا كبيرًا في سياساتهم، ليس بسبب اختلاف المبادئ والمصالح، بل بسبب اختلاف طرائقهم في الوصول إلى مبادئهم ومصالحهم. وهناك طريقتان يسلكهما صانع القرار في تحقيق غاياته:","ومعرفة أي الطريقتين يسلك صانع القرار تُسعف كثيرًا في التنبؤ بمواقفه، فمثلًا حين تُدرك دولة قوية أن دولة ضعيفة تتآمر عليها فلا نشك أن صانع القرار سوف يتحرك لإبطال هذا التآمر، لكن ما سنختلف فيه هو الأسلوب الذي سيعوّل عليه للوصول إلى هذه النتيجة، هل سيلجأ إلى ردة فعل سريعة من خلال توجيه ضربة مباشرة أو سيبدأ بتنسيق انقلاب على النظام أو سيلجأ إلى تحييد هذا الخطر بطريقة تدريجية؟ هذا كله يعتمد على معرفة أي الأسلوبين يتصف به صانع القرار."],"key":"قد يمتلك صانعو القرار الهدف ذاته، لكن نجد اختلافًا كبيرًا في سياساتهم، ليس بسبب اختلاف المبادئ والمصالح، بل بسبب اختلاف طرائقهم في الوصول إلى مبادئهم ومصالحهم.","items":[{"h":"الطريقة الصفرية","x":"وهي الوصول المباشر والسريع للهدف، فلا يعتمد على التدرج في تحقيق المكاسب، بل يتجه إليها مباشرة، وهي طريقة حادة وذات كلفة عالية، وتنشأ عنها آثار جوهرية. ومن أمثلة متبعي هذا الأسلوب الرئيس الأمريكي دونالد ترمب والرئيس الفنزويلي هوغو تشافيز."},{"h":"الطريقة التراكمية","x":"وهي الوصول التدريجي والمرن للهدف، فهو يعتمد على أسلوب المكاسب المتراكمة، ومن هؤلاء الرئيس التركي أردوغان ورئيس الوزراء الماليزي السابق مهاتير محمد."}]},{"t":"هل يصلح النموذج للتفسير؟","p":["هذه هي الركائز الثلاث التي ينبني عليها النموذج الإرشادي، وواضح أن النموذج مفصّل على مقاس التنبؤ في أساسه، لكن هل يصلح النموذج للتفسير كذلك؟","الواقع أنه صالح، لكن في حالة التفسير لا نحتاج إلى ثلاثية النموذج كلها، بل يكفي البُعد الأول منها، وهو بُعد البحث عن إرادة الفاعل. والسبب أن القدرة والطريقة أصبحتا جزءًا من التاريخ، فالفعل وقع وانتهى، فلا داعي لسؤال: هل سيقع؟ ولا لسؤال: كيف سيقع؟ وإنما أصبح هناك سؤال واحد، وهو: لماذا وقع؟ وسؤال \"لماذا\" سؤال تفسيري بطبيعة الحال، ولن نصل إليه إلا من خلال الكشف عن إرادة صانع القرار بطرقها الأربع التي ذكرناها سابقًا.","فعلى سبيل المثال، حين حصل طوفان الأقصى في السابع من أكتوبر، لم يعد منطقيًا سؤال: هل سيقع الطوفان؟ أو سؤال: كيف سيقع الطوفان؟ لأن الطوفان وقع وانقضى، وإنما يبقى سؤال الغاية، لماذا وقع الطوفان؟ وهنا يمكن التعويل على الركيزة الأولى من ركائز النموذج، وهي ركيزة الكشف عن إرادة صانع قرار الطوفان، إما من خلال المعلومات المباشرة من دوائر صناعة القرار في حماس، أو من خلال تتبع خطابات يحيى السنوار وحواراته، وقد تضمنت الكثير من الأسباب الشارحة لعملية الطوفان، أو من خلال مراجعة السيرة النفسية ليحيى السنوار نفسه، إذا أخذنا بالطريقة الفرويدية."],"key":"لكن في حالة التفسير لا نحتاج إلى ثلاثية النموذج كلها، بل يكفي البُعد الأول منها، وهو بُعد البحث عن إرادة الفاعل."},{"t":"مقارنة بين النظرية والنموذج","p":["بعد شرح ماهية النموذج أصبح ممكنًا الآن التفريق بينه وبين النظرية، فإذا كانت النظرية تنطلق من المعرفة إلى الفاعل فإن النموذج ينطلق من الفاعل إلى المعرفة، فالمعرفة في النموذج هي نتاج دراسة معطيات الفاعل نفسه، أما النظرية فالمعرفة فيها نتاج معطيات فاعلين آخرين تفترض تماثلها مع فاعلين جدد. وهذا الفارق ينبني عليه نجاة النموذج من أزمة الملاءمة (Crisis of Relevance)، والتي تعد التهديد الأكبر لمشروعية النظرية، فصحيح أن المعرفة التي تكتنزها النظرية هي نتاج دراسة فاعلين بالضرورة، لكن الصحيح كذلك أن النظرية لم تنطلق من الفاعل نفسه الذي يُراد استشراف قراره، وإنما انطلقت من فاعلين آخرين افتراضًا أن ما تحقق معهم سيتحقق مع غيرهم، وما يقلل جدوى ذلك أن السياقات الثقافية وإرادات الفاعلين لا تتماثل بالضرورة كما ذكرنا سابقًا، في حين النموذج ينطلق من الفاعل نفسه، والسياق نفسه.","علاوة على ذلك، يسعى النموذج للوصول، أما النظرية فهي تدّعي الوصول؛ فالنموذج يزوّد الباحث بالخطوات المنهجية لدراسة الفاعل سعيًا لاستشراف الخيار الذي سيذهب إليه، في حين تقدّم النظرية جوابًا مسبقًا تفترض فيه معرفته لذلك الخيار، فالنموذج ينطلق من الأسئلة إيمانًا بالخصوصية، والنظرية تنطلق من الإجابات إيمانًا بالتعميم، فالنموذج يبدأ من السؤال والنظرية تبدأ من الإجابة.","ولأن النموذج يقدم أسئلة والنظرية تقدم إجابات، فإن النموذج يجعل مهمة الباحث بنائية، في حين تجعل النظرية مهمة الباحث تطبيقية؛ ففي النموذج يبني الباحث الإجابة تدريجيًا، أما في النظرية فهو يمتلك إجابة جاهزة، وتبقى مهمته في تطبيقها.","فعلى سبيل المثال، لو سألنا عند ابتداء الأزمة الخليجية 2017، كيف سيكون دور وزير الخارجية الأمريكي ريكس تيلرسون في الأزمة؟ هنا نحن أمام خيارين:","في الخيار الأول سنجد أن النظرية لا تضيف شيئًا حقيقيًا؛ لأن المسؤول ربما يكون أكبر من موقعه وربما يكون أصغر منه، فلا نستطيع أن نحكم إلا بعد دراسة المسؤول نفسه. أما في الخيار الثاني فسنجد أننا لم ننطلق من إجابات مسبقة، بل من أسئلة مرشدة، فالنموذج يسأل: ما طبيعة توجهات وزير الخارجية الأمريكي؟ وما طبيعة المصالح التي تربطه بطرفي الصراع؟ وما طبيعة إمكاناته وقدراته؟ هذه الأسئلة ونحوها تجعلنا نقترب من توليد إجابات ملائمة لمعطيات الواقع.","ولنأخذ مثالًا آخر يزيد الأمر وضوحًا، لنفترض أننا نريد أن نتنبأ بمستقبل الصراع بين أمريكا والصين، ووجدنا نظرية تخبرنا أن 80% من الحالات التاريخية التي شهدت بروز قوى صاعدة على حساب القوى السائدة انتهت بصراع عسكري مباشر، فبناء على هذه النظرية سوف نتنبأ بنشوب صراع عسكري بين الصين وأمريكا.","لكن النموذج لا يقدم لنا الأمر بهذه السهولة، وإنما يفرض علينا أسئلة نابعة من طبيعة أطراف هذا الصراع وطبيعة النظام الدولي وطبيعة التحديات التي يواجهها كل منهما، ثم بعد دراسة كل هذه المعطيات يمكن التعويل على الاستقراء التاريخي أو حتى الأقيسة المباشرة في سبيل تعزيز أحد السيناريوهات الناتجة عن البحث النموذجي. ففي البحث النموذجي سوف نسأل عن رغبات صانع القرار الصيني، وتاريخه في صنع القرار، وطبيعة تفضيلاته في معالجة الأزمات، وطبيعة المساحة التي يملكها في الداخل الصيني، وطبيعة تموضعه في النظام الإقليمي والدولي، وأنماط المصالح والمبادئ التي يسعى لها، وغير ذلك من الأسئلة التي تدور في فلك ثلاثية النموذج السابقة: الإرادة والقدرة والطريقة.","هكذا نجد أنفسنا أكثر قربًا من الواقع حين ننطلق من النموذج، ولذلك مهمة استشراف صناعة القرار لا تصح بوجود نظرية، بل بوجود نموذج؛ لأن النظرية تعني الحكم على حالة بناء على حالات سابقة؛ ولأن ظروف الحالات لا تتماثل، ولأن الخيارات الإنسانية تعيش جدلية الدوافع والنوازع، فإن وجود نظرية لن يكون مجديًا، بل أحيانًا يكون صانعًا لوعي مزيّف وأوهام مقدّرة كما ذكرنا سابقًا. أما النموذج فهو لا يصنع معرفة مسبقة تجاه الفاعل الاجتماعي، وإنما ينطلق من دراسة الفاعل نفسه، وبالتالي لن يكون معرّضًا لأزمة الملاءمة.","والفارق بين النموذج والنظرية لا يقتصر على ما سبق، بل يمتد إلى طبيعة التعامل مع أدوات المعرفة، فإذا كانت النظرية تعتمد على القياس في التأسيس، فإن النموذج يعتمد على القياس للتأكيد، فالقياس في النظرية يؤسس لمعرفة تدعي العموم، في حين القياس في النموذج هو مرجّح لأحد الاحتمالات الناشئة عن دراسة الفاعل نفسه، في السياق نفسه.","وعمومًا يمكن تلخيص الفروق بين النموذج والنظرية وفقًا لمعطيات الجدول أدناه:"],"key":"فإذا كانت النظرية تنطلق من المعرفة إلى الفاعل فإن النموذج ينطلق من الفاعل إلى المعرفة","items":[{"h":"خيار النظرية","x":"وهو أن نأتي بنظرية من السياسة المقارنة تحمل إجابة مسبقة لهذا السؤال، فنلجأ مثلًا إلى نظرية السياسة البيروقراطية Bureaucratic politics، التي تعتمد على أن صانع القرار يحدد موقفه بناء على طبيعة تموضعه داخل البيروقراطية، وهذا ما تعبر عنه مقولة: \"موقفك يعتمد على موقعك\"."},{"h":"خيار النموذج","x":"وهو أن ننطلق من دراسة شخصية تيلرسون نفسه وفقًا لثلاثية النموذج، فننظر في طبيعة توجهاته ومصالحه ورغباته وإمكاناته النفسية والخارجية."}],"table":{"head":["وجه المقارنة","النموذج","النظرية"],"rows":[["المنطلق","الفاعل","المعرفة"],["الأداة","السؤال","الإجابة"],["الطبيعة","بنائي","إسقاطي"],["الموقف","محايد","متحيّز"],["التموضع","خاص","عام"],["الصلاحية","مطلقة","نسبية"],["القياس","مؤكد","مؤسِّس"]]}},{"t":"خصائص النموذج: الموضوعية والدقة والجزم","p":["أخيرًا نقول إن النموذج لن يحقق طموح أوغست كونت بجعل البحث السياسي يقوم على \"قواعد يقينية\" على حد تعبيره، لكن في نهاية المطاف سيتصف بثلاث خصائص:"],"key":"والجزم هو الحكم المطمئن مع وجود احتمال نادر لا يُلتفت له، أما اليقين فهو انتفاء الاحتمال المعارض انتفاءً قطعيًا.","items":[{"h":"أولًا: الموضوعية","x":"فهو لا ينطلق من تحيّزات مسبقة، سواءً أكانت بسبب مجال نشأة النظرية أو بسبب تحيزات الباحث الثقافية."},{"h":"ثانيًا: الدقة","x":"لأن النموذج يتطلب الانطلاق من الفاعل نفسه، والنظرية إسقاط، والإسقاط تنشأ عنه فجوة الملاءمة."},{"h":"ثالثًا: الجزم","x":"ونعني بالجزم أن يكون المرء مطمئنًا اطمئنانًا تامًا بأن صانع القرار سيتصرف بالاتجاه الفلاني. فعلى سبيل المثال لو سألنا حين اندلع طوفان الأقصى: هل ستتحرك الجيوش العربية لنصرة غزة؟ النموذج يوصلك هنا إلى جواب جازم، وهو أنها لن تتحرك، وذلك بناء على معرفة إرادات صناع القرار من خلال التراكم التاريخي. نعم، قد يتحرك جيش في لحظة فارقة، لكن هذا احتمال أقرب إلى المستحيل، لكن ليس كاستحالة أن يصل الماء إلى درجة مئة ولا يغلي. ولذلك نقول إن النموذج قد يوصل إلى الجزم، لكنه لا يوصل إلى اليقين، والجزم هو الحكم المطمئن مع وجود احتمال نادر لا يُلتفت له، أما اليقين فهو انتفاء الاحتمال المعارض انتفاءً قطعيًا. وليس المقصود أن الجزم من المخرجات اللازمة للنموذج، ولكن القصد أن الوصول إلى الجزم لا يكون إلا من خلال النموذج، وهذا الجزم الذي أوصلنا إليه النموذج لا يمكن أن توصلنا إليه النظرية."}]}],"examples":[{"who":"التبعية العربية للمنظومة الغربية، ومقولة ابن خلدون","x":"فمثلًا لو رأينا حالة التبعية العربية للمنظومة الغربية، فهنا يمكن الاتكاء على المقولة التفسيرية لابن خلدون بأن المغلوب مولع بالغالب، لكن هذا قد لا يعكس الواقع، فقد تكون هناك أسباب أخرى أمنية أو اجتماعية أو سياسية أدت إلى ذلك.","pg":50},{"who":"مستويات المصلحة: صانع القرار والدولة والإقليم","x":"مستوى صانع القرار نفسه؛ كتحقيقه بعض المكتسبات لأغراض انتخابية، ومستوى الدولة، كالدخول في الحرب لأجل نهب الثروات، ومستوى إقليمي/دولي، كأن تتوافق مجموعة من الدول على إبقاء حالة الحرب مشتعلة في منطقة ما لأسباب متعلقة بالمصالح أو المبادئ أو كليهما.","pg":52},{"who":"رئيس دولة يرفض الوقوف مع دولة أخرى","x":"فمثلًا يمكن لرئيس دولة أن يرفض الوقوف مع دولة أخرى، مع أن مبادئه ومصالحه تقتضي ذلك، وإذا فتشنا عن السبب سنجده يعود إلى كراهية شخصية بينه وبين رئيس تلك الدولة. والعكس كذلك صحيح، فقد يقف رئيس دولة مع دولة أخرى لا لأجل مصلحة الدولة أو مبادئها، بل لأجل قوة العلاقة الشخصية بين الرئيسين.","pg":53},{"who":"أوكرانيا والناتو وصانع القرار الروسي","x":"فلنفترض مثلًا أن أوكرانيا كانت تسعى للانضمام إلى الناتو، ماذا ينبغي أن يفعل صانع القرار الروسي في هذه الحالة؟ هنا يضع الباحث نفسه مكان صانع القرار الروسي ويستظهر السيناريوهات المحتملة.","pg":56},{"who":"صانع القرار الإيراني","x":"فمثلًا حين نتتبع التراكم التاريخي لسلوك صانع القرار الإيراني سنجده لا يميل أبدًا إلى المواجهة العسكرية المباشرة حتى مع ضعف الطرف الآخر، وإنما يفضل دائمًا الضربات الموضعية، إن اضطر لذلك، أو التحرك من خلال وكلائه وحلفائه، لكنه في كل الأحوال لا يفضل أبدًا أن تكون الدولة الإيرانية نفسها جزءًا من أي مواجهة مباشرة.","pg":57},{"who":"صانع قرار جبان متردد","x":"فربما يمتلك صانع القرار كل القدرات الداخلية والخارجية الكافية لردع دولةٍ ما عن تجاوزها، لكنه يتصف بالجُبن والتردد مما يجعلنا نميل إلى أنه لن يتحرك تجاه هذا التجاوز.","pg":58},{"who":"الرئيس الأمريكي وإيران والأغلبية البرلمانية وشركات الأسلحة","x":"فمثلًا قد يريد الرئيس الأمريكي عقد اتفاقية مع إيران، لكن لديه عائق داخلي يتمثل في الأغلبية البرلمانية، أو ربما يريد الرئيس إيقاف نزاع حربي في إحدى دول العالم، لكن ضغط شركات الأسلحة يمنعه من اتخاذ هذا القرار.","pg":58},{"who":"صانع قرار في نظام شمولي","x":"فمثلًا قد يرغب صانع قرار في نظام شمولي أن يُشعل نزاعًا مع دولة أخرى، لكن يخشى من تأثير قبيلة كبيرة في مجتمعه، أو طائفة أو فئة عرقية أو غير ذلك.","pg":58},{"who":"تركيا واليونان","x":"فمثلًا يمكن أن تكون تركيا قادرة ذاتيًا وداخليًا على توجيه ضربة لليونان في بعض الجزر المتنازع عليها، لكن تركيا تدرك أن ذلك يؤدي إلى توريطها مع الولايات المتحدة أو الاتحاد الأوروبي أو على الأقل تهديدها بالفصل السابع في دوائر مجلس الأمن، فتحجم عن ذلك مع امتلاكها القدرة الذاتية والداخلية.","pg":58},{"who":"صانع قرار مستبد","x":"فيأتي عند صانع قرار مستبد فيعتقد أنه قادر على فعل ما يشاء، لكنه لا ينتبه لضعف قدراته النفسية أو وجود قيود مجتمعية وثقافية تمنعه من فعل ما يريد.","pg":60},{"who":"دونالد ترمب وهوغو تشافيز (الطريقة الصفرية)","x":"ومن أمثلة متبعي هذا الأسلوب الرئيس الأمريكي دونالد ترمب والرئيس الفنزويلي هوغو تشافيز.","pg":60},{"who":"أردوغان ومهاتير محمد (الطريقة التراكمية)","x":"ومن هؤلاء الرئيس التركي أردوغان ورئيس الوزراء الماليزي السابق مهاتير محمد.","pg":60},{"who":"دولة قوية ودولة ضعيفة تتآمر عليها","x":"فمثلًا حين تُدرك دولة قوية أن دولة ضعيفة تتآمر عليها فلا نشك أن صانع القرار سوف يتحرك لإبطال هذا التآمر، لكن ما سنختلف فيه هو الأسلوب الذي سيعوّل عليه للوصول إلى هذه النتيجة، هل سيلجأ إلى ردة فعل سريعة من خلال توجيه ضربة مباشرة أو سيبدأ بتنسيق انقلاب على النظام أو سيلجأ إلى تحييد هذا الخطر بطريقة تدريجية؟","pg":60},{"who":"طوفان الأقصى ويحيى السنوار وحماس","x":"حين حصل طوفان الأقصى في السابع من أكتوبر، لم يعد منطقيًا سؤال: هل سيقع الطوفان؟ أو سؤال: كيف سيقع الطوفان؟ لأن الطوفان وقع وانقضى، وإنما يبقى سؤال الغاية، لماذا وقع الطوفان؟ ... إما من خلال المعلومات المباشرة من دوائر صناعة القرار في حماس، أو من خلال تتبع خطابات يحيى السنوار وحواراته، وقد تضمنت الكثير من الأسباب الشارحة لعملية الطوفان، أو من خلال مراجعة السيرة النفسية ليحيى السنوار نفسه، إذا أخذنا بالطريقة الفرويدية.","pg":61},{"who":"ريكس تيلرسون والأزمة الخليجية 2017","x":"لو سألنا عند ابتداء الأزمة الخليجية 2017، كيف سيكون دور وزير الخارجية الأمريكي ريكس تيلرسون في الأزمة؟","pg":63},{"who":"أمريكا والصين","x":"لنفترض أننا نريد أن نتنبأ بمستقبل الصراع بين أمريكا والصين، ووجدنا نظرية تخبرنا أن 80% من الحالات التاريخية التي شهدت بروز قوى صاعدة على حساب القوى السائدة انتهت بصراع عسكري مباشر، فبناء على هذه النظرية سوف نتنبأ بنشوب صراع عسكري بين الصين وأمريكا.","pg":64},{"who":"الجيوش العربية وغزة (طوفان الأقصى)","x":"لو سألنا حين اندلع طوفان الأقصى: هل ستتحرك الجيوش العربية لنصرة غزة؟ النموذج يوصلك هنا إلى جواب جازم، وهو أنها لن تتحرك، وذلك بناء على معرفة إرادات صناع القرار من خلال التراكم التاريخي.","pg":67},{"who":"الماء ودرجة الغليان","x":"نعم، قد يتحرك جيش في لحظة فارقة، لكن هذا احتمال أقرب إلى المستحيل، لكن ليس كاستحالة أن يصل الماء إلى درجة مئة ولا يغلي.","pg":67}],"quotes":[{"x":"الإنسان من وجهة النظر الفيزيائية ليس أكثر من منظومة خلايا، ومن جهة النظر العقلية ليس أكثر من منظومة تصورات","by":"دوركايم","pg":54},{"x":"العلوم السياسية من دون سير ذاتية هي نوع من التحنيط","by":"هارولد لاسويل (نقلًا عن ديفيد باتريك)","pg":56},{"x":"موقفك يعتمد على موقعك","by":"مقولة تعبر عن نظرية السياسة البيروقراطية","pg":63},{"x":"قواعد يقينية","by":"أوغست كونت","pg":66}],"notes":["لا شك أن الحديث هنا عن النموذج سيكون محدودًا بحقل هذه الدراسة، وهو الحقل السياسي، لكن الأمل أن هذه الدراسة الموجزة تفتح باب النقاش حول هذا النموذج لتستبين بذلك إمكاناته وثغراته على حدٍّ سواء، مما يتيح المجال بعد ذلك لتوسيع النموذج ليشمل سائر الحقول الاجتماعية."],"quiz":[{"q":"ما العنصران اللازمان في أداة التفكير ولا يتوافران في النظرية؟","o":["الإطلاق والعموم","التفسير والتحقق","الصفرية والتراكمية","المبادئ والمصالح"]},{"q":"ما ثلاثية النموذج الإرشادي؟","o":["الإرادة والقدرة والطريقة","الوصف والتفسير والتنبؤ","المبادئ والمصالح والرغبات","الذاتية والداخلية والخارجية"]},{"q":"ما المحددات الثلاثة لإرادة الفاعل؟","o":["المبادئ والمصالح والرغبات","القدرة الذاتية والداخلية والخارجية","المعلومات والتاريخ والتفهم","الصفرية والتراكمية والمختلطة"]},{"q":"أي طرق الكشف عن إرادة صانع القرار يعوّل عليها الباحثون عادة لصعوبة الوصول إلى المقربين؟","o":["التراكم التاريخي لصانع القرار","المعلومات المباشرة","المدخل الفرويدي","التفهّم"]},{"q":"في التفسير، أي ركائز النموذج يكفي؟","o":["الإرادة وحدها","القدرة وحدها","الطريقة وحدها","الثلاث مجتمعة دائماً"]},{"q":"ما الفرق بين الجزم واليقين عند المؤلف؟","o":["الجزم حكم مطمئن مع احتمال نادر لا يُلتفت له، واليقين انتفاء الاحتمال المعارض قطعاً","لا فرق بينهما","اليقين أضعف من الجزم","الجزم يصل إليه النظرية لا النموذج"]}],"sort":{"t":"رغبة أم مصلحة؟","s":"من جدول المؤلف للفروق بين الرغبة والمصلحة.","bins":["الرغبة","المصلحة"],"items":[["وجدانية",0],["عقلية",1],["بسيطة وواضحة",0],["مركبة ومعقدة",1],["ليس بالضرورة نافعة",0],["نافعة بالضرورة",1]]},"match":{"t":"الطريقة الصفرية أم التراكمية؟","s":"صل كل طريقة بوصفها وأمثلة المؤلف عليها.","l":"الطريقة","r":"وصفها ومثالها","pairs":[["الطريقة الصفرية","الوصول المباشر والسريع للهدف، ومن أمثلتها ترمب وتشافيز"],["الطريقة التراكمية","الوصول التدريجي والمرن للهدف، ومن أمثلتها أردوغان ومهاتير محمد"]]}},{"k":"conclusion","t":"نحو إعادة تموضع النظرية: من التأسيس إلى التأكيد","q":"أين مكان النظرية الصحيح: قبل النموذج أم بعده؟","sections":[{"t":"النظرية بعد النموذج لا قبله","p":["بعد توضيح كل من النظرية والنموذج أصبح التموضع المنطقي للنظرية واضحًا، وهو أنها مرحلة ما بعد النموذج لا قبله، أي إنها في سياق التأكيد لا التأسيس، فالواجب أولًا الانتهاء من دراسة الموقف بناء على محددات النموذج الثلاثة، ثم في سياق الترجيح يأتي استثمار النظرية، فالنظرية مهمة لتوسيع الفهم لا لتأسيسه.","فعلى سبيل المثال، حين يحصل توتر بين بلدين ديمقراطيين فإن نظرية السلام الديمقراطي تقدّم لنا تنبؤًا جاهزًا، وهو أن الدول الديمقراطية لا تتحارب فيما بينها، وبالتالي سوف نتوقع أن النزاع بينهما سيُحل بالطرق السلمية. هذا بناءً على التموضع الحالي للنظرية في البحث الاجتماعي، لكن التموضع المقترح هو أن يتم ترحيل النظرية من مرحلة التأسيس إلى مرحلة التأكيد، فيبدأ الباحث أولًا بدراسة طبائع صناع القرار في البلدين وطبيعة حساباتهم، وأنماط المصالح المحفزة للصراع، وقدرات الطرفين الداخلية والدولية، ثم بعد دراسة ذلك قد يترجح أن الحرب ستقع، لوجود مؤشرات قوية، وقد يتساوى عنده الأمر، وقد يترجح أن الحرب لا تقع. هنا تحديدًا تتجلى أهمية النظرية، وهي أنها تأتي لتؤكد أحد الاحتمالات التي لا تبدو معطيات الواقع قادرة على تأكيدها أو حين لا تتوافر المعطيات عند الباحثين وصناع القرار، فإنه حينها يمكن التعويل على النظرية لسد فراغ النموذج."],"key":"فالنظرية مهمة لتوسيع الفهم لا لتأسيسه."},{"t":"النظرية معرفة احتياطية","p":["فدور النظرية إذن أن تسد فراغ النموذج؛ أي إن النظرية معرفة احتياطية لا نلجأ إليها إلا عند تعثّر النموذج وتوقفه، أما ما دام النموذج قادرًا على الاشتغال فلا حاجة للنظرية، وبذلك تكون النظرية مستوعبة ضمن النموذج، وأن مهمتها تكمن في تقوية النموذج لا الحلول محله.","على أنه من المهم الإشارة إلى أن النظريات ليست سواء في وزنها التفسيري أو التنبؤي، فمثلًا لو قارنا بين نظرية السلام الديمقراطي ونظرية السياسة البيروقراطية لوجدنا أن الأولى أقوى وأرسخ، فالمرء يمكن أن يطمئن كثيرًا لفكرة أن الدول الديمقراطية لا تتحارب، لكن لا يمكن أن يطمئن إلى أن المواقع ترسم المواقف كما تفترض النظرية البيروقراطية. ومع ذلك، فإن البداية يجب أن تكون مع النموذج بصرف النظر عن قوة النظرية وضعفها؛ لأن النموذج يدعو إلى الاشتباك المباشر مع الواقع دون استعارة إجابات مسبقة والتورّط في تحيزاتها، فهو الأكثر ضمانًا للاقتراب من الواقع أكبر درجة ممكنة."],"key":"أي إن النظرية معرفة احتياطية لا نلجأ إليها إلا عند تعثّر النموذج وتوقفه"},{"t":"الخطأ في التموضع لا في الوجود","p":["إذن وجود النظريات ليس خطأ، الخطأ في تموضعها، فحين تكون النظرية زاوية للتفكير يُلتفت إليها بعد الاشتباك المباشر مع الواقع فهي بلا شك مفيدة، لكن أن تكون النظرية إطارًا مسبقًا يؤطر وعي الباحث تجاه الظاهرة فهو مشكل؛ ليس لأنها لا تضيف شيئًا فحسب، بل لأنها كذلك تعرّضه لمشكلتي استثارة التحيّز وتسرّبه، لا سيما مع أصالة التحيّز والتقليد في النفس الإنسانية، ومع وجود فجوات طبيعية فارقة بين مجال نشأة النظرية ومجال استثمارها."],"key":"إذن وجود النظريات ليس خطأ، الخطأ في تموضعها"}],"examples":[{"who":"بلدان ديمقراطيان ونظرية السلام الديمقراطي","x":"حين يحصل توتر بين بلدين ديمقراطيين فإن نظرية السلام الديمقراطي تقدّم لنا تنبؤًا جاهزًا، وهو أن الدول الديمقراطية لا تتحارب فيما بينها، وبالتالي سوف نتوقع أن النزاع بينهما سيُحل بالطرق السلمية.","pg":68},{"who":"نظرية السلام الديمقراطي مقابل نظرية السياسة البيروقراطية","x":"لو قارنا بين نظرية السلام الديمقراطي ونظرية السياسة البيروقراطية لوجدنا أن الأولى أقوى وأرسخ، فالمرء يمكن أن يطمئن كثيرًا لفكرة أن الدول الديمقراطية لا تتحارب، لكن لا يمكن أن يطمئن إلى أن المواقع ترسم المواقف كما تفترض النظرية البيروقراطية.","pg":68}],"quotes":[],"notes":[],"quiz":[{"q":"أين التموضع الصحيح للنظرية كما يقترحه المؤلف؟","o":["بعد النموذج، في سياق التأكيد لا التأسيس","قبل النموذج، إطاراً مسبقاً","بدلاً من النموذج","لا مكان لها في البحث"]},{"q":"متى نلجأ إلى النظرية بحسب الخاتمة؟","o":["عند تعثّر النموذج وتوقفه، فهي معرفة احتياطية","في بداية كل بحث","حين تتوافر كل المعطيات","حين نريد اليقين"]},{"q":"ما الخطأ الحقيقي في استعمال النظريات عند المؤلف؟","o":["تموضعها، لا وجودها","وجودها أصلاً","كثرتها","قدمها"]}]}],"labs":[{"id":"netanyahu","ch":"المبحث الأول","title":"هل كانت إسرائيل ستدير حرب السابع من أكتوبر بالطريقة نفسها مع رئيس وزراء آخر؟","scene":"حين ندرس سلوك الدولة الإسرائيلية؛ من الطبيعي الانطلاق من شخصية بنيامين نتنياهو نفسه.","theory":{"name":"عقلانية الدولة (الدولة صندوق أسود)","claim":"افتراض \"عقلانية الدولة\"، وأن الدولة عبارة عن صندوق أسود Black Box لا يصدر عنه سوى الاختيارات العقلانية.","answer":"الدولة تتصرف بعقلانية مؤسسية أيًا كان على رأسها."},"model":{"will":["ما الذي يريده نتنياهو نفسه في تدبير الحرب؟"],"ability":["ما دور المؤسسات الإسرائيلية التشريعية والأمنية في تقييد قراره أو دعمه؟"],"approach":[]},"author":"فلو كان هناك شخص آخر غير نتنياهو في السلطة لكان سلوك إسرائيل مختلفًا في تدبير حرب السابع من أكتوبر، ولا ينفي ذلك دور المؤسسات الإسرائيلية التشريعية والأمنية، لكنه يؤكد على أن لنتنياهو اليد العليا في تحديد السياسة الإسرائيلية.","pg":16},{"id":"brezhnev","ch":"المبحث الثاني","title":"لماذا غزا الاتحاد السوفيتي أفغانستان؟","scene":"قد نستمر في تحليل أسباب غزو الاتحاد السوفيتي لأفغانستان مستلهمين كل المعطيات الدولية والسياسية والأمنية والاقتصادية.","theory":{"name":"الفاعل العقلاني الساعي إلى مصلحته","claim":"بافتراضهم أن الفاعل الاجتماعي يتحرك لتحقيق غاية واحدة، وهي \"المصلحة\"، ويتوسّل إليها بوسيلة واحدة، وهي \"العقلانية\".","answer":"الغزو حساب عقلاني للمصالح الدولية والسياسية والأمنية والاقتصادية."},"model":{"will":["ما الحالة النفسية لبريجينيف حين اتخذ القرار؟","هل كانت الرغبة (ردة الفعل العاطفية) أثقل من المصلحة؟"],"ability":[],"approach":[]},"author":"ثم نكتشف أن الأمر لا علاقة له بكل تلك المسوغات العقلية، وإنما هي ردة فعل نفسية ناتجة عن حالة الإحباط النفسي التي مر بها رئيس الاتحاد السوفيتي ليونيد بريجينيف نتيجة رفض مجلس الشيوخ الأمريكي التصديق على معاهدة الحد من الأسلحة الاستراتيجية بين البلدين. هكذا نجد أن حرية الفاعل لا تزال تصر على عرقلة مشروع التعميم.","pg":24},{"id":"democracy_development","ch":"المبحث الثاني","title":"هل الديمقراطية سبب التنمية أم أنهما تزامنا فقط؟","scene":"فلنفترض أننا درسنا ستة نظم ديمقراطية واكتشفنا أنها جميعها تمتلك تنمية اقتصادية.","theory":{"name":"الاستقراء (الربط بين الديمقراطية والتنمية)","claim":"يجب الربط بين الديمقراطية والتنمية حتى وإن لم يرتبطا واقعًا، كما انتهى إلى ذلك الخبيران الأمريكيان لورن كارنر وكينيث والك.","answer":"الديمقراطية تنتج التنمية."},"model":{"will":[],"ability":[],"approach":[]},"author":"فهل وجودهما معًا، أعني الديمقراطية والتنمية الاقتصادية، يدل على علاقة سببية تلازمية أم أنهما تزامنا معًا في هذه الحالات؟ فقد تكون التنمية عائدة إلى السياسات المالية والضريبية أو عائدة لموجهات ثقافية في المجتمع، وقد يكون الربط بينهما متكلّفًا يُعبّر عما ينبغي أن يكون عليه الحال.","pg":29},{"id":"revolutions","ch":"المبحث الثاني","title":"هل تفشل أي ثورة قادمة إن لم تكن لها قيادة مسبقة؟","scene":"لو تتبعنا خمس ثورات شعبية ناجحة، ووجدناها كلها تشترك في وجود قيادة مسبقة للثورة.","theory":{"name":"تعميم استقرائي من خمس ثورات","claim":"كل الثورات الناجحة المدروسة اشتركت في وجود قيادة مسبقة.","answer":"لن تنجح أي ثورة قادمة إلا بوجود قيادة."},"model":{"will":["مدى تحقق الإجماع الوطني على مطلب الثورة"],"ability":["طبيعة الحياة السياسية في المجتمع","مستوى الوعي","طبيعة الوحدات الاجتماعية وتوازناتها","طبيعة الهويات الفرعية"],"approach":[]},"author":"فهل يمكن الحكم على أي ثورة قادمة بأنها لن تنجح إلا بوجود قيادة؟ لا نستطيع ذلك، فالأمر يتوقف على عوامل عديدة، منها طبيعة الحياة السياسية في المجتمع، ومستوى الوعي، وطبيعة الوحدات الاجتماعية وتوازناتها، وطبيعة الهويات الفرعية، ومدى تحقق الإجماع الوطني على مطلب الثورة، وغير ذلك.","pg":30},{"id":"turkey_armenia","ch":"المبحث الثاني","title":"هل ستحل تركيا خلافها مع أرمينيا عسكريًا؟ وإيران مع أذربيجان؟","scene":"ولنفترض أننا استقرينا الدول المتوسطة فوجدنا أن ثمانين بالمئة منها تحل مشاكلها مع الدول الصغيرة المجاورة لها بالحل العسكري.","theory":{"name":"تعميم استقرائي عن الدول المتوسطة","claim":"ثمانون بالمئة من الدول المتوسطة تحل مشاكلها مع الدول الصغيرة المجاورة لها بالحل العسكري.","answer":"تركيا ستحل خلافها مع أرمينيا عسكريًا، وإيران ستحل مشاكلها مع أذربيجان عسكريًا."},"model":{"will":["طبيعة صانع القرار"],"ability":["طبيعة النظام السياسي","طبيعة التحالفات الإقليمية والدولية لكلا الطرفين","طبيعة التركيبة المجتمعية في كلا البلدين"],"approach":[]},"author":"فهذا لا يجعلنا نتوقع أبدًا أن تركيا ستحل خلافها مع أرمينيا حلًا عسكريًا، ولا أن إيران ستحل مشاكلها مع أذربيجان حلًا عسكريًا. الأمر يتوقف على طبيعة النظام السياسي وطبيعة صانع القرار، وطبيعة التحالفات الإقليمية والدولية لكلا الطرفين، وطبيعة التركيبة المجتمعية في كلا البلدين، وعلى غير ذلك من العوامل. وهكذا نجد أن الاستقراء وحده لا يملك مشروعية التعدية، وإنما لكل سياق معطياته المتفرّدة.","pg":31},{"id":"saddam","ch":"المبحث الثالث","title":"كيف وصل صدام حسين إلى السلطة؟","scene":"فلو أردت دراسة كيفية وصول صدام حسين إلى السلطة، بماذا ينفعني أن ألجأ إلى نظرية العصبية عند ابن خلدون كإطار نظري للدراسة؟","theory":{"name":"نظرية العصبية عند ابن خلدون","claim":"الوصول إلى السلطة يكون بالعصبية بالمفهوم الخلدوني.","answer":"وصل صدام إلى السلطة بالعصبية."},"model":{"will":["لماذا سعى صدام إلى السلطة وما الذي أراده؟"],"ability":["هل استعان صدام بعصبية بالمفهوم الخلدوني أم وصل دونها؟"],"approach":[]},"author":"لأنه يمكن أن يكون صدام وصل إلى السلطة دون عصبية بالمفهوم الخلدوني، ويمكن أنه وصل مستعينًا بها، فإن كان وصل دونها عرفت أنها غير صالحة، وإن كان وصل بها عرفت حينها أنها صالحة، لكني لم أصل لذلك إلا بعد دراسة الموضوع!","pg":36},{"id":"criminal","ch":"المبحث الثالث","title":"ما الذي يفسر النزعة الإجرامية لدى أحد صناع القرار؟","scene":"ولو أردنا مثلًا تفسير النزعة الإجرامية لدى أحد صناع القرار فسنجد أنفسنا أمام نظريات كثيرة تدّعي التفسير.","theory":{"name":"النظرية البيولوجية، والفرويدية، والإحباط العدوانية، والتفسير الاجتماعي","claim":"هناك النظرية البيولوجية، التي ترى أن المجرم تعتريه إكراهات بيولوجية تدفعه للإجرام، وهناك النظرية النفسية الفرويدية التي ترى أن الإنسان يمتلك منذ مولده طاقة عدوانية، وهناك نظرية الإحباط العدوانية التي ترى أن المجرمين هم أناس تعرضوا لإحباطات متكررة، وهناك نظرية التفسير الاجتماعي للسلوك الإجرامي التي ترى أن الجريمة نتيجة الضغوط الاجتماعية ونحوها.","answer":"أربعة أجوبة جاهزة متنافسة: البيولوجيا، أو الطاقة العدوانية، أو الإحباط، أو الضغوط الاجتماعية."},"model":{"will":["ما الذي يكشفه تاريخ صانع القرار وسيرته النفسية عن دوافعه؟"],"ability":[],"approach":[]},"author":"فلو اعتمد الباحث على أي نظرية مسبقة فإنه في النهاية لن يحكم على الظاهرة إلا بعد دراستها، فماذا يستفيد الباحث من تأطير بحثه منذ البداية بإحدى هذه النظريات ما دام أنه لن يستطيع الوصول إلى التفسير الحقيقي إلا بعد دراسة الظاهرة؟","pg":36},{"id":"putin_poland","ch":"المبحث الثالث","title":"هل سيوسع الرئيس بوتين الصراع مع بولندا؟","scene":"لو أخذنا إحدى هذه النظريات وأردنا توظيفها في التنبؤ بموقف الرئيس بوتين من توسيع الصراع مع بولندا مثلًا.","theory":{"name":"الواقعية أو الليبرالية أو البنائية","claim":"فالواقعية التي تنطلق من فرضية أن صانع القرار يتحرك بحثًا عن المصلحة بآلية القوة، وأنه في سياق السعي إليها لا يلتفت إلى الأبعاد القانونية أو الأخلاقية، والليبرالية التي تستند إلى العقلانية وتفضيلات التبادل السلمي للمصالح واحترام القانون الدولي، والبنائية التي تعتمد على البعد الثقافي والهوياتي.","answer":"كل نظرية تعطي جوابًا مسبقًا: القوة، أو التبادل السلمي واحترام القانون، أو الهوية والثقافة."},"model":{"will":["ما الذي يكشفه تاريخ بوتين في القرار عن إرادته؟"],"ability":["ما حدود قدرات صانع القرار الروسي؟"],"approach":[]},"author":"كيف سندرك تحقق ذلك في صانع القرار إلا بعد دراسة تاريخ صانع القرار وحدود قدراته؟","pg":40},{"id":"armenia","ch":"المبحث الثالث","title":"هل ستدخل أرمينيا سباق تسلح بعد أن حصلت أذربيجان على أسلحة نوعية من تركيا؟","scene":"وأردنا التنبؤ بسلوك صانع القرار الأرميني بعد أن حصلت أذربيجان على أسلحة نوعية من تركيا.","theory":{"name":"نظرية توازن القوى","claim":"تفترض أن الدول تسعى دائمًا لتحقيق توازن قوى مع خصومها.","answer":"سوف نتوقع من صانع القرار الأرميني أن يدخل في سباق تسلح ليحقق توازن القوى."},"model":{"will":["هل يخشى صانع القرار الأرميني على حظوظه الانتخابية؟"],"ability":["هل صانع القرار الأرميني شجاع أم جبان يفضّل التهدئة على التصعيد؟","هل تحتمل الحالة الاقتصادية لبلاده الكُلفة المالية لسباق التسلح؟"],"approach":["هل يميل إلى التصعيد أم إلى التهدئة؟"]},"author":"لكن قد لا يتحقق ذلك بالضرورة، فربما يكون صانع القرار الأرميني جبانًا فيفضّل التهدئة على التصعيد، وربما يخشى من الكُلفة المالية لسباق التسلّح فتؤثر على الحالة الاقتصادية لبلاده، وهو ما ينعكس بطبيعة الحال على حظوظه الانتخابية. هكذا نجد أنفسنا، بسبب حرية الفاعل ونسبية دوافعه، غير قادرين على الاكتفاء بالنظرية في تحديد السيناريو المرجح، وإنما الأمر يتطلب دراسة سياقية للفاعل نفسه.","pg":41},{"id":"match","ch":"المبحث الثالث","title":"من سيفوز في مباراة برشلونة وريال مدريد؟","scene":"الذي يتنبأ بنتيجة المباراة قبل بدئها، فهو يرى مثلًا أن النتيجة سوف تنتهي بهزيمة برشلونة أمام ريال مدريد بهدفين مقابل لا شيء، بناء على تقييمه لأداء الفريقين في المباريات السابقة.","theory":{"name":"التنبؤ من المباريات السابقة (تشبيه لشأن النظرية)","claim":"تقييم أداء الفريقين في المباريات السابقة يحدد النتيجة.","answer":"هزيمة برشلونة أمام ريال مدريد بهدفين مقابل لا شيء."},"model":{"will":[],"ability":[],"approach":[]},"author":"الآن ما فائدة هذا التنبؤ؟ ليس له أي فائدة سوى إشباع فضول المتابع، أما النتيجة فلن تُعرف إلا من خلال متابعة المباراة إلى أن تنهيها صافرة الحكم. وهكذا هي النظرية إلى حدٍّ بعيد، تقدم تنبؤًا لا يمكن التحقق منه إلا من خلال دراسة الفاعل نفسه، أي بعد أن يكون الأمر تحصيل حاصل.","pg":41},{"id":"prospect","ch":"المبحث الثالث","title":"متى يخاطر صانع القرار؟ مثال مدرب كرة القدم","scene":"ويمكن أن نشبّه المسألة بوضع مدرب فريق كرة القدم، حين يكون فريقه خاسرًا فإن الأدعى في تلك الحالة أن يدفع بخطة هجومية متهورة، لأنه في وضع الخاسر، ولكن لو كان فائزًا أو متعادلًا فلن يكون متقبلًا للمخاطرة.","theory":{"name":"نظرية المترقب (Prospect Theory)","claim":"تفترض النظرية أن صانع القرار يبدأ بالمخاطرة حين يشعر بأنه في وضع الخاسر، أما حين يشعر بأنه في وضع الرابح فإنه سيتجنب المخاطرة.","answer":"الخاسر يخاطر، والرابح يتجنب المخاطرة."},"model":{"will":["كيف نجزم بأن صانع القرار مقتنع بأنه في وضع الخاسر؟","وما مستوى الخسارة الذي يدفع صانع القرار للمخاطرة؟"],"ability":["هل يخشى أن المخاطرة ستجلب له مزيدًا من الخسارة؟"],"approach":[]},"author":"لكن هذه النظرية لا يبدو من النافع الانطلاق منها؛ لأنه ربما يكون صانع القرار في وضع الخاسر ومع ذلك لا يتقبل المخاطرة، إما لأنه أصلًا لا يعتقد أنه في وضع الخاسر، وإما أنه يخشى أن المخاطرة ستجلب له مزيدًا من الخسارة. ما دام أن النظرية لا تمنح جوابًا على هذين السؤالين فإن الانطلاق منها لا يفيد شيئًا عمليًا.","pg":42},{"id":"hymans","ch":"المبحث الثالث","title":"هل ستملك إيران في عهد أحمدي نجاد السلاح النووي؟","scene":"وقد حاول جاك هايمانز أن يطور نظرية للتنبؤ على الأقل في مجال تطوير القدرات النووية.","theory":{"name":"نظرية هايمانز: القوميون التعارضيون","claim":"رأى أن الذهاب باتجاه تطوير القدرات النووية لا يظهر إلا مع فئة واحدة من القادة، وهم القوميون التعارضيون Oppositional Nationalists، ويقصد بهم أولئك الذين يملكون رؤى متشددة تجاه خصومهم (منطق نحن وهم).","answer":"إيران في عهد أحمدي نجاد وكوريا الشمالية في عهد كيم إيل سونغ ستملكان النووي."},"model":{"will":["صحيح أن نجاد يتصف بالقومية التعارضية في زمن رئاسته، فهل يكفي ذلك؟"],"ability":["ما القيود السياقية التي تعتري صانع القرار؟"],"approach":[]},"author":"لكن هذه النظرية تغيّب تأثير القيود السياقية التي تعتري صانع القرار، ولذلك لم يصدق تنبؤه في حالة أحمدي نجاد، فصحيح أن نجاد يتصف بالقومية التعارضية في زمن رئاسته، لكن هذا لا يكفي لحسم خياراته إلا من خلال دراسته وفقًا للنموذج الإرشادي الذي سنقترحه في هذه الدراسة.","pg":43},{"id":"homans_trump","ch":"المبحث الثالث","title":"لماذا لم يقرر ترمب إسقاط النظام الإيراني في حرب يونيو 2025؟","scene":"لو قلنا: لماذا لم يقرر ترمب إسقاط النظام الإيراني في حرب يونيو 2025؟ سيكون الجواب أن ذلك لم يكن من مصلحته في ذلك الوقت.","theory":{"name":"المقدمة الكبرى عند جورج هومانز","claim":"كل من لا يرى مصلحته راجحة في فعلٍ ما فإنه من المرجح ألا يفعله، والمقدمة الثانية: ترمب لم ير مصلحته راجحة في إسقاط النظام الإيراني.","answer":"فإذن النتيجة أنه لن يسقطه."},"model":{"will":["كيف نعرف أن ترمب يرى فيها مصلحة أو لا يرى؟","ما هي المصلحة بمنظور صانع القرار نفسه؟"],"ability":[],"approach":[]},"author":"لكن هذا المقترح لا يحل الأمر؛ لأن السؤال: وكيف نعرف أن ترمب يرى فيها مصلحة أو لا يرى! فلا شك أن الناس عمومًا تتبع مصالحها، هذا ليس اكتشافًا مدهشًا، لكن المعضلة أننا لا نعرف ما هي المصلحة بمنظور صناع القرار إلا بعد دراستهم فرادى، وهكذا نعود جميعًا إلى المربع الأول.","pg":44},{"id":"bloch_gulf","ch":"المبحث الرابع","title":"هل العادات في المجتمع الخليجي تخفي التغير أم تخفي الاستمرار؟","scene":"يمكن أن يعتمد الباحث على نظرية مارك بلوخ التي مفادها أن العادات والتقاليد تصنع وهم الاستمرار من أجل إخفاء التغير الاجتماعي.","theory":{"name":"نظرية مارك بلوخ","claim":"العادات والتقاليد تصنع وهم الاستمرار من أجل إخفاء التغير الاجتماعي.","answer":"العادات في المجتمع الخليجي تخفي تغيرًا اجتماعيًا حاصلًا."},"model":{"will":[],"ability":[],"approach":[]},"author":"فقد يأخذها الباحث ويؤمن بها وتهيمن على وعيه دون أن يشعر، في حين واقعه يسير على العكس، فإذا كان مارك يرى أن العادات تخلق وهم الاستمرار لتخفي التغيرات الاجتماعية، فربما يكون المجتمع الخليجي مثلًا يسير عكس ذلك، بأن يخلق وهم التغير الاجتماعي ليخفي استمرار تمسكه بالعادات والتقاليد!","pg":47},{"id":"arab_dependency","ch":"المبحث الخامس","title":"لماذا التبعية العربية للمنظومة الغربية؟","scene":"فمثلًا لو رأينا حالة التبعية العربية للمنظومة الغربية.","theory":{"name":"مقولة ابن خلدون التفسيرية","claim":"بأن المغلوب مولع بالغالب.","answer":"التبعية العربية ولع المغلوب بالغالب."},"model":{"will":[],"ability":[],"approach":[]},"author":"لكن هذا قد لا يعكس الواقع، فقد تكون هناك أسباب أخرى أمنية أو اجتماعية أو سياسية أدت إلى ذلك.","pg":50},{"id":"tillerson","ch":"المبحث الخامس","title":"كيف سيكون دور ريكس تيلرسون في الأزمة الخليجية 2017؟","scene":"لو سألنا عند ابتداء الأزمة الخليجية 2017، كيف سيكون دور وزير الخارجية الأمريكي ريكس تيلرسون في الأزمة؟","theory":{"name":"نظرية السياسة البيروقراطية (Bureaucratic politics)","claim":"تعتمد على أن صانع القرار يحدد موقفه بناء على طبيعة تموضعه داخل البيروقراطية، وهذا ما تعبر عنه مقولة: \"موقفك يعتمد على موقعك\".","answer":"موقف تيلرسون يحدده موقعه وزيرًا للخارجية."},"model":{"will":["ما طبيعة توجهات وزير الخارجية الأمريكي؟","وما طبيعة المصالح التي تربطه بطرفي الصراع؟","ما رغباته؟"],"ability":["وما طبيعة إمكاناته وقدراته النفسية والخارجية؟"],"approach":[]},"author":"في الخيار الأول سنجد أن النظرية لا تضيف شيئًا حقيقيًا؛ لأن المسؤول ربما يكون أكبر من موقعه وربما يكون أصغر منه، فلا نستطيع أن نحكم إلا بعد دراسة المسؤول نفسه. أما في الخيار الثاني فسنجد أننا لم ننطلق من إجابات مسبقة، بل من أسئلة مرشدة ... هذه الأسئلة ونحوها تجعلنا نقترب من توليد إجابات ملائمة لمعطيات الواقع.","pg":63},{"id":"us_china","ch":"المبحث الخامس","title":"هل سينشب صراع عسكري بين أمريكا والصين؟","scene":"لنفترض أننا نريد أن نتنبأ بمستقبل الصراع بين أمريكا والصين.","theory":{"name":"نظرية القوى الصاعدة والقوى السائدة","claim":"80% من الحالات التاريخية التي شهدت بروز قوى صاعدة على حساب القوى السائدة انتهت بصراع عسكري مباشر.","answer":"سوف نتنبأ بنشوب صراع عسكري بين الصين وأمريكا."},"model":{"will":["رغبات صانع القرار الصيني","أنماط المصالح والمبادئ التي يسعى لها"],"ability":["طبيعة المساحة التي يملكها في الداخل الصيني","طبيعة تموضعه في النظام الإقليمي والدولي","طبيعة التحديات التي يواجهها كل من الطرفين"],"approach":["تاريخه في صنع القرار","طبيعة تفضيلاته في معالجة الأزمات"]},"author":"لكن النموذج لا يقدم لنا الأمر بهذه السهولة، وإنما يفرض علينا أسئلة نابعة من طبيعة أطراف هذا الصراع وطبيعة النظام الدولي وطبيعة التحديات التي يواجهها كل منهما، ثم بعد دراسة كل هذه المعطيات يمكن التعويل على الاستقراء التاريخي أو حتى الأقيسة المباشرة في سبيل تعزيز أحد السيناريوهات الناتجة عن البحث النموذجي.","pg":64},{"id":"aqsa_why","ch":"المبحث الخامس","title":"لماذا وقع طوفان الأقصى؟ النموذج في خدمة التفسير","scene":"حين حصل طوفان الأقصى في السابع من أكتوبر، لم يعد منطقيًا سؤال: هل سيقع الطوفان؟ أو سؤال: كيف سيقع الطوفان؟ لأن الطوفان وقع وانقضى، وإنما يبقى سؤال الغاية، لماذا وقع الطوفان؟","theory":null,"model":{"will":["المعلومات المباشرة من دوائر صناعة القرار في حماس","تتبع خطابات يحيى السنوار وحواراته","مراجعة السيرة النفسية ليحيى السنوار نفسه، إذا أخذنا بالطريقة الفرويدية"],"ability":[],"approach":[]},"author":"وهنا يمكن التعويل على الركيزة الأولى من ركائز النموذج، وهي ركيزة الكشف عن إرادة صانع قرار الطوفان، إما من خلال المعلومات المباشرة من دوائر صناعة القرار في حماس، أو من خلال تتبع خطابات يحيى السنوار وحواراته، وقد تضمنت الكثير من الأسباب الشارحة لعملية الطوفان، أو من خلال مراجعة السيرة النفسية ليحيى السنوار نفسه، إذا أخذنا بالطريقة الفرويدية.","pg":61},{"id":"aqsa_armies","ch":"المبحث الخامس","title":"هل ستتحرك الجيوش العربية لنصرة غزة حين اندلع طوفان الأقصى؟","scene":"لو سألنا حين اندلع طوفان الأقصى: هل ستتحرك الجيوش العربية لنصرة غزة؟","theory":null,"model":{"will":["إرادات صناع القرار العرب كما يكشفها التراكم التاريخي لسلوكهم"],"ability":[],"approach":[]},"author":"النموذج يوصلك هنا إلى جواب جازم، وهو أنها لن تتحرك، وذلك بناء على معرفة إرادات صناع القرار من خلال التراكم التاريخي. نعم، قد يتحرك جيش في لحظة فارقة، لكن هذا احتمال أقرب إلى المستحيل، لكن ليس كاستحالة أن يصل الماء إلى درجة مئة ولا يغلي. ولذلك نقول إن النموذج قد يوصل إلى الجزم، لكنه لا يوصل إلى اليقين.","pg":67},{"id":"iran_direct","ch":"المبحث الخامس","title":"هل ستدخل الدولة الإيرانية نفسها مواجهة عسكرية مباشرة؟","scene":"حين نتتبع التراكم التاريخي لسلوك صانع القرار الإيراني.","theory":null,"model":{"will":["ما الذي يكشفه التراكم التاريخي لسلوك صانع القرار الإيراني؟"],"ability":[],"approach":["هل يفضل المواجهة المباشرة أم الضربات الموضعية أم التحرك من خلال الوكلاء والحلفاء؟"]},"author":"سنجده لا يميل أبدًا إلى المواجهة العسكرية المباشرة حتى مع ضعف الطرف الآخر، وإنما يفضل دائمًا الضربات الموضعية، إن اضطر لذلك، أو التحرك من خلال وكلائه وحلفائه، لكنه في كل الأحوال لا يفضل أبدًا أن تكون الدولة الإيرانية نفسها جزءًا من أي مواجهة مباشرة.","pg":57},{"id":"turkey_greece","ch":"المبحث الخامس","title":"هل ستضرب تركيا اليونان في الجزر المتنازع عليها؟","scene":"يمكن أن تكون تركيا قادرة ذاتيًا وداخليًا على توجيه ضربة لليونان في بعض الجزر المتنازع عليها.","theory":null,"model":{"will":[],"ability":["القدرة الذاتية والداخلية متوافرة","القدرة الخارجية: التوريط مع الولايات المتحدة أو الاتحاد الأوروبي","التهديد بالفصل السابع في دوائر مجلس الأمن"],"approach":[]},"author":"لكن تركيا تدرك أن ذلك يؤدي إلى توريطها مع الولايات المتحدة أو الاتحاد الأوروبي أو على الأقل تهديدها بالفصل السابع في دوائر مجلس الأمن، فتحجم عن ذلك مع امتلاكها القدرة الذاتية والداخلية.","pg":58},{"id":"democratic_peace","ch":"نحو إعادة تموضع النظرية","title":"توتر بين بلدين ديمقراطيين: هل ستقع الحرب؟","scene":"حين يحصل توتر بين بلدين ديمقراطيين.","theory":{"name":"نظرية السلام الديمقراطي","claim":"الدول الديمقراطية لا تتحارب فيما بينها.","answer":"سوف نتوقع أن النزاع بينهما سيُحل بالطرق السلمية."},"model":{"will":["طبائع صناع القرار في البلدين وطبيعة حساباتهم","أنماط المصالح المحفزة للصراع"],"ability":["قدرات الطرفين الداخلية والدولية"],"approach":[]},"author":"فيبدأ الباحث أولًا بدراسة طبائع صناع القرار في البلدين وطبيعة حساباتهم، وأنماط المصالح المحفزة للصراع، وقدرات الطرفين الداخلية والدولية، ثم بعد دراسة ذلك قد يترجح أن الحرب ستقع، لوجود مؤشرات قوية، وقد يتساوى عنده الأمر، وقد يترجح أن الحرب لا تقع. هنا تحديدًا تتجلى أهمية النظرية، وهي أنها تأتي لتؤكد أحد الاحتمالات التي لا تبدو معطيات الواقع قادرة على تأكيدها.","pg":68}],"concepts":[{"term":"الوصف","def":"رصد السلوك الإنساني ومتعلقاته كما هي متحققة في الواقع، وغاية الوصف صناعة الفهم."},{"term":"التفسير","def":"تسبيب نظام العلاقات بين الظواهر ومدخلاتها ومخرجاتها، وغاية التفسير صناعة المعنى. والمقصود بالتفسير الكشف عن أسباب الأفعال والظواهر الاجتماعية."},{"term":"التنبؤ","def":"التعويل على قواعد معرفية موجِّهة لاستشراف السلوك الإنساني، وغاية التنبؤ صناعة التهيؤ. والتنبؤ هو استشراف مآل الفعل الإنساني بناء على قواعد موضوعية."},{"term":"التقييم","def":"تعبر عن المعرفة المعيارية تجاه السلوك الإنساني، وغاية التقييم صناعة الموقف."},{"term":"نظريات الفاعلية","def":"نظريات تعوّل على دور الفاعل في صناعة السياسة الخارجية أكثر من تعويلها على دور البنية.","en":"agency theories"},{"term":"نظرية الدور","def":"تسعى لفهم صناعة القرار من خلال صانع القرار نفسه، لا من خلال دراسة إرادته وقدرته وطريقته، بل من خلال زاوية واحدة، وهي تصور صانع القرار لطبيعة الدور الملائم لدولته إقليميًا ودوليًا.","en":"Role Theory"},{"term":"الموقفية والنزوعية","def":"جدل يتمحور حول مصادر وعي صانع القرار التي تشكّل سلوكه السياسي، أهي ذاتية المنشأ كما تفترض النزوعية؟ أم أنها نتاج البيئة المحيطة بالفرد كما ترى الموقفية؟","en":"Situationism / Dispositionism"},{"term":"الصندوق الأسود","def":"افتراض أن الدولة عبارة عن صندوق أسود لا يصدر عنه سوى الاختيارات العقلانية.","en":"Black Box"},{"term":"الاختزالية","def":"فخ ينفيه المؤلف عن طرحه: لأننا نقول إن صناعة القرار في السياسة تتمركز حول الفرد، والتمركز لا ينفي ما سواه بقدر ما يثبت أولويته.","en":"Reductionism"},{"term":"المنهجية الفردية","def":"ترى أن كل موقف مركب يعود في الحقيقة إلى أفراد بعينهم تشكّل مواقفهم وميولهم الإطار الذي ينتمون إليه، وهو ما يقتضي التعويل على البعد النفسي في التفسير.","en":"Methodological individualism"},{"term":"النظرية","def":"المعرفة التفسيرية المتحققة في سياقٍ ما."},{"term":"الفرضية","def":"الفرضية هي النظرية قبل ثبوتها، والنظرية هي الفرضية بعد ثبوتها، ذلك أن الفرضية في الأصل تفسير مؤقت للظاهرة يضعه الباحث إلى أن يتأكد من ثبوته."},{"term":"الملاحظة","def":"الملاحظة إخبار لا تفسير، فهي تخبر عن حالة تم رصدها وملاحظتها."},{"term":"القانون الاجتماعي","def":"معرفة بدهية عابرة للسياقات، كقول الناس: \"كل ممنوع مرغوب\"، وهو غالبًا مطرد لا يخضع للنسبية الثقافية."},{"term":"الأنوميا","def":"مصطلح الأنوميا الدوركايمي لا يعد نظرية؛ لأنه يصف المجتمع في حالة سيولة المعايير بما يجعل قدرته ضئيلة على التوجيه الأخلاقي لأفراده، لكنه لا يفسّر تلك الحالة."},{"term":"مجال النشأة","def":"السياق الذي اختُبرت فيه فرضية النظرية وثبت تحققها."},{"term":"مجال الاستثمار","def":"السياق الذي يُراد توظيف النظرية فيه."},{"term":"حرية الفاعل","def":"يختلف الفاعل الاجتماعي عن الفاعل الطبيعي في قضية جوهرية، وهي حرية الإرادة، فالفاعل الاجتماعي يتمتع بإرادة حرة، خلافًا للفاعل الطبيعي الذي يسير بنوعٍ من الحتمية."},{"term":"نسبية الدافع","def":"المصلحة مفهوم نسبي لا يمكن تعميمه، فهو يختلف من فاعل لآخر بحسب تصوراته الثقافية وميوله النفسية."},{"term":"الفعل المجاني","def":"فعل لا نستطيع أن نفهم سببه، فعل عبثي لا يستطيع علم الاجتماع قول شيء حياله وما عليه إلا أن يستقيل (بتعريف بورديو)."},{"term":"التوقع العقلاني","def":"ما يسميه أوغست كونت، ويكتفي به الباحث إذا سلّم أن كل فاعل يتوسّل بالعقلانية لتحقيق مصالحه."},{"term":"القياس","def":"الحكم على حالة مجهولة بناء على حالة معلومة."},{"term":"الاستقراء","def":"الحكم على حالة مجهولة بناء على \"حالات\" معلومة، أو على حد تعبير روبير بلانشي \"انطلاق من الوقائع إلى القوانين\". وتراكم الأقيسة هو ما يسمى بـ \"الاستقراء\". والاستقراء لغة من القرو، وهو التتبع."},{"term":"الاستقراء المنطقي","def":"الحكم على الكلي لوجود ذلك الحكم في جزئيات ذلك الكلي."},{"term":"التلازم والتزامن","def":"معضلة التفريق بين العنصر الملازم والعنصر المتزامن: هل وجود أمرين معًا يدل على علاقة سببية تلازمية أم أنهما تزامنا معًا في هذه الحالات؟"},{"term":"الصلاحية والصحة","def":"في النظرية الاجتماعية نبحث عادةً عن \"الصلاحية\"، أما في النظرية الطبيعية فالبحث عادةً عن \"الصحة\"."},{"term":"الموضوعية","def":"وصفٌ للباحث الذي لا يجعل تحيزاته المسبقة تحكم نتائج بحثه."},{"term":"العلمية","def":"وصفٌ لعملية البحث التي تستبعد كل فرضية بلا دليل."},{"term":"نظرية توازن القوى","def":"تفترض أن الدول تسعى دائمًا لتحقيق توازن قوى مع خصومها."},{"term":"نظرية المترقب","def":"حاولت أن تجيب على سؤال: متى يخاطر صانع القرار؟ وتفترض أن صانع القرار يبدأ بالمخاطرة حين يشعر بأنه في وضع الخاسر، أما حين يشعر بأنه في وضع الرابح فإنه سيتجنب المخاطرة.","en":"Prospect Theory"},{"term":"القوميون التعارضيون","def":"أولئك الذين يملكون رؤى متشددة تجاه خصومهم (منطق نحن وهم).","en":"Oppositional Nationalists"},{"term":"المقدمة الكبرى","def":"ما اقترحه جورج هومانز لإضفاء خاصية التعميم، كأن نقول: كل من لا يرى مصلحته راجحة في فعلٍ ما فإنه من المرجح ألا يفعله.","en":"Major Premise"},{"term":"نظرية الإحباط العدوانية","def":"ترى أن المجرمين هم أناس تعرضوا لإحباطات متكررة، وتاليًا الدافع للجريمة هو التعبير عن ذلك الإحباط.","en":"Frustration Aggression Theory"},{"term":"استثارة التحيّز","def":"الميل غير الواعي عند الباحث لإثبات منطقية اختياره للنظرية."},{"term":"الانحياز التأكيدي","def":"النزعة إلى جمع المعلومات أو تفسيرها بشكل انتقائي يؤكد المعتقدات أو التوقعات أو الفرضيات السابقة (بتعريف الجمعية الأمريكية لعلم النفس).","en":"Confirmation bias"},{"term":"تسرّب التحيّز","def":"التحيز الذي تستبطنه النظرية ثمة إمكانيّة لتسربه لوعي الباحث، لا سيما إن كانت النظرية ذات هالة في مجالها."},{"term":"الافتراضات الضمنية","def":"ما يسميه ألفن جولدنر الافتراضات التي لا مفر منها، \"فسواء أحب علماء الاجتماع ذلك أم كرهوه، عرفوه أم جهلوه، ففي النهاية سوف ينظمون بحوثهم بالنظر إلى افتراضاتهم المسبقة\".","en":"background assumptions"},{"term":"العقلانية المحدودة وسلوك الاستكفاء","def":"خلاصتهما أن الإنسان حين تتكاثر أمامه الخيارات فإنه لا يبدي النظر الكافي فيها جميعًا، وإنما يكتفي عادةً بالموازنة بين خيارين أو ثلاثة."},{"term":"أداة التفكير","def":"أن يختارها الباحث إطارًا نظريًا مسبقًا للتفكير في محل البحث؛ فينظر للواقع من خلالها وبها. ويجب أن يتوافر فيها عنصران: الإطلاق، بألا تكون متحيّزة لفرضيات مسبقة، والعموم، بألا تكون خاصة بسياق معين."},{"term":"النموذج الإرشادي","def":"دراسة شروط إنتاج سلوك صانع القرار من خلال البحث في إرادته وقدراته وطرائقه."},{"term":"المبادئ","def":"الأفكار المعيارية التي يؤمن بها الإنسان عند تحديد موقفه من الخير والشر.","en":"Principles"},{"term":"المصالح","def":"كل ما يحقق نفعًا غير متعلق بالمبادئ، وهي حاضرة على ثلاثة مستويات؛ مستوى صانع القرار نفسه، ومستوى الدولة، ومستوى إقليمي/دولي.","en":"Interests"},{"term":"الرغبات","def":"مطلوبات المرء المرتبطة بعواطفه، كالكره والحب والطمع والخوف والحسد وغيرها من ضروب العاطفة.","en":"Desires"},{"term":"التصورات","def":"القناعات الكامنة في وعي الفرد والتي تنتج أفكاره وممارساته وتحدد كيفية فهمه للأمور."},{"term":"السيرة النفسية والتاريخ النفسي","def":"يتتبع الباحث السيرة النفسية لصانع القرار منذ طفولته، وينظر في المؤثرات الأساسية ليفهم من خلالها طبيعة محددات تفكيره (المدخل الفرويدي).","en":"Psychobiography / Psychohistory"},{"term":"التفهّم","def":"أن يتقمّص الباحث موقف صانع القرار ويضع نفسه موضعه، فيفكر في كيفية التصرّف بحسب طبيعة الموقف وخصائصه.","en":"Empathy"},{"term":"مشكلة الإتاحة","def":"إذ ليس من المتيسّر لعموم الباحثين الوصول إلى معلومات من المقرّبين لصانع القرار.","en":"The problem of access"},{"term":"القدرة","def":"مجموع إمكانات صانع القرار التي تسمح بتحقيق مراده."},{"term":"القدرة الذاتية","def":"تشمل القدرات النفسية والعقلية في شخصية صانع القرار."},{"term":"القدرة الداخلية","def":"متعلقة بمقدرة صانع القرار على تجاوز العوائق الداخلية، كطبيعة النظام السياسي، وعقيدة الدولة، وهوية المجتمع، وتوازنات الفاعلين السياسيين."},{"term":"القدرة الخارجية","def":"متعلقة بقدرة صانع القرار على تجاوز العوائق الخارجية، كمصالح القوى الكبرى أو القانون الدولي أو طبيعة قواعد الاشتباك الإقليمي ونحو ذلك."},{"term":"الطريقة الصفرية","def":"الوصول المباشر والسريع للهدف، فلا يعتمد على التدرج في تحقيق المكاسب، بل يتجه إليها مباشرة، وهي طريقة حادة وذات كلفة عالية، وتنشأ عنها آثار جوهرية."},{"term":"الطريقة التراكمية","def":"الوصول التدريجي والمرن للهدف، فهو يعتمد على أسلوب المكاسب المتراكمة."},{"term":"نظرية السياسة البيروقراطية","def":"تعتمد على أن صانع القرار يحدد موقفه بناء على طبيعة تموضعه داخل البيروقراطية، وهذا ما تعبر عنه مقولة: \"موقفك يعتمد على موقعك\".","en":"Bureaucratic politics"},{"term":"أزمة الملاءمة","def":"التهديد الأكبر لمشروعية النظرية: أن النظرية لم تنطلق من الفاعل نفسه الذي يُراد استشراف قراره، وإنما انطلقت من فاعلين آخرين افتراضًا أن ما تحقق معهم سيتحقق مع غيرهم.","en":"Crisis of Relevance"},{"term":"الجزم","def":"أن يكون المرء مطمئنًا اطمئنانًا تامًا بأن صانع القرار سيتصرف بالاتجاه الفلاني. والجزم هو الحكم المطمئن مع وجود احتمال نادر لا يُلتفت له."},{"term":"اليقين","def":"انتفاء الاحتمال المعارض انتفاءً قطعيًا."},{"term":"نظرية السلام الديمقراطي","def":"تقدّم تنبؤًا جاهزًا، وهو أن الدول الديمقراطية لا تتحارب فيما بينها."},{"term":"النظرية معرفة احتياطية","def":"دور النظرية أن تسد فراغ النموذج؛ أي إن النظرية معرفة احتياطية لا نلجأ إليها إلا عند تعثّر النموذج وتوقفه."}],"refs_count":39,"refs_detail":{"ar":25,"en":14},"id":"nmodel","author":"د. نايف بن نهار","pub":"مؤسسة وعي للدراسات والأبحاث","bio":"الدكتور نايف بن نهار الشمري، حاصل على بكالوريوس الدراسات الإسلامية من جامعة قطر، والماجستير والدكتوراه في الفقه وأصوله من الجامعة الإسلامية العالمية بماليزيا، والماجستير في العلاقات الدولية والدبلوماسية من جامعة الأخوين. أسس مؤسسة وعي للدراسات والأبحاث، ومن مؤلفاته: «مقدمة في علم العلاقات الدولية»، و«الديمقراطية كما هي»، و«مقدمة في علم المنطق»، و«مقدمة في علم الأصول».","lead":"كيف يتنبأ المحلل بقرار دولة؟ هل يبدأ من نظرية جاهزة، أم من صانع القرار نفسه؟ رحلة تفاعلية في الكتاب كاملاً: تقرأ الحجة بنص المؤلف، وتختبرها بيدك في «مختبر المحلل»."};
